// 病句 코스 2 — tools/make_bingju.py 가 tools/bingju/c02.json 에서 만든다. 직접 고치지 않는다.
(window.BJ=window.BJ||{})[2]=[[{"o":["随着青藏铁路的全线通车，使沿线许多原本闭塞的牧区与外界的经济往来日益频繁。","横断山脉山高谷深，气候垂直变化显著，因而孕育了极为丰富的动植物资源。","唐代诗人王维的山水诗意境空灵，被后人誉为“诗中有画，画中有诗”。","适度的焦虑能够提高人的注意力，但长期处于紧张状态则会损害身心健康。"],"a":0,"type":"주어 결여","why":"“随着…，使…” 때문에 문장에 주어가 없다. 使를 빼면 “往来”의 주어 “经济往来”가 살아난다.","fix":"随着青藏铁路的全线通车，沿线许多原本闭塞的牧区与外界的经济往来日益频繁。","words":[["横断山脉","Héngduàn Shānmài","헝돤산맥"],["孕育","yùnyù","낳아 기르다"],["闭塞","bìsè","(교통·소식이) 막혀 외지다"],["空灵","kōnglíng","맑고 신비롭다"],["誉为","yùwéi","~라고 칭송하다"],["焦虑","jiāolǜ","초조함, 불안"]],"tr":["칭짱 철도가 전 구간 개통되면서, 철도를 따라 있는 원래 외지고 막혀 있던 많은 목축 지역과 바깥세상의 경제 교류가 날로 잦아졌다.","헝돤산맥은 산이 높고 골짜기가 깊으며 높이에 따라 기후가 크게 달라져, 동식물 자원이 매우 풍부하게 자라났다.","당나라 시인 왕유의 산수시는 분위기가 맑고 신비로워, 후세 사람들에게 '시 속에 그림이 있고 그림 속에 시가 있다'는 칭송을 받았다.","적당한 불안은 사람의 주의력을 높일 수 있지만, 오랫동안 긴장 상태에 있으면 몸과 마음의 건강을 해친다."],"ow":[[["闭塞","bìsè","(교통·소식이) 막혀 외지다"],["往来","wǎnglái","오가다, 교류"],["频繁","pínfán","잦다"],["牧区","mùqū","목축 지역"]],[["横断山脉","Héngduàn Shānmài","헝돤산맥"],["孕育","yùnyù","낳아 기르다"]],[["空灵","kōnglíng","맑고 신비롭다"],["誉为","yùwéi","~라고 칭송하다"]],[["焦虑","jiāolǜ","초조함, 불안"],["损害","sǔnhài","해치다"],["适度","shìdù","적당하다"]]]},{"o":["敦煌莫高窟现存洞窟七百余个，壁画四万五千多平方米，堪称世界上规模最大的佛教艺术宝库之一。","这家企业之所以能在激烈的竞争中脱颖而出，是因为它始终把技术创新放在首位。","通过对三江源地区连续十年的生态监测，让科学家们发现藏羚羊的种群数量已明显回升。","每年秋季，成千上万只丹顶鹤从东北迁徙到江苏盐城的滩涂越冬。"],"a":2,"type":"주어 결여","why":"“通过…，让…” 때문에 “发现”의 주어가 없다. “科学家们”이 让 뒤에 갇혀 주어 노릇을 못 한다.","fix":"通过对三江源地区连续十年的生态监测，科学家们发现藏羚羊的种群数量已明显回升。","words":[["三江源","Sānjiāngyuán","싼장위안(세 강의 발원지)"],["藏羚羊","zànglíngyáng","티베트영양"],["莫高窟","Mògāo Kū","막고굴"],["堪称","kānchēng","~라 할 만하다"],["脱颖而出","tuō yǐng ér chū","두각을 나타내다"],["丹顶鹤","dāndǐnghè","두루미"],["迁徙","qiānxǐ","이동하다"],["滩涂","tāntú","갯벌"]],"tr":["둔황 막고굴에는 지금 동굴 700여 개와 벽화 4만 5천여 제곱미터가 남아 있어, 세계에서 규모가 가장 큰 불교 예술의 보고 가운데 하나라 할 만하다.","이 기업이 치열한 경쟁 속에서 두각을 나타낼 수 있었던 것은 늘 기술 혁신을 가장 앞에 두었기 때문이다.","싼장위안 지역을 10년 동안 이어서 생태 관측한 결과, 과학자들은 티베트영양의 개체 수가 뚜렷하게 회복되었다는 것을 발견했다.","해마다 가을이면 수많은 두루미가 둥베이에서 장쑤성 옌청의 갯벌로 옮겨 와 겨울을 난다."],"ow":[[["莫高窟","Mògāo Kū","막고굴"],["堪称","kānchēng","~라 할 만하다"]],[["脱颖而出","tuō yǐng ér chū","두각을 나타내다"],["激烈","jīliè","치열하다"],["首位","shǒuwèi","첫자리"]],[["三江源","Sānjiāngyuán","싼장위안(세 강의 발원지)"],["藏羚羊","zànglíngyáng","티베트영양"]],[["丹顶鹤","dāndǐnghè","두루미"],["迁徙","qiānxǐ","이동하다"],["滩涂","tāntú","갯벌"]]]},{"o":["京剧融合了徽剧、汉剧和昆曲等多种戏曲的精华，至今已有两百多年的历史。","在当地政府与环保志愿者的共同努力下，使濒临干涸的白洋淀再现了碧波荡漾的景象。","人体在睡眠过程中会分泌大量生长激素，因此充足的睡眠对青少年的发育尤为重要。","由于长期受到季风的影响，我国东部地区夏季高温多雨，冬季寒冷干燥。"],"a":1,"type":"주어 결여","why":"“在…下，使…” 때문에 “再现”의 주어가 없다. 使를 빼야 “白洋淀”이 주어가 된다.","fix":"在当地政府与环保志愿者的共同努力下，濒临干涸的白洋淀再现了碧波荡漾的景象。","words":[["濒临","bīnlín","~에 처하다, 직면하다"],["干涸","gānhé","(물이) 말라붙다"],["白洋淀","Báiyáng Diàn","바이양뎬(호수)"],["碧波荡漾","bì bō dàng yàng","푸른 물결이 일렁이다"],["徽剧","huījù","후이극(안후이 지방극)"],["昆曲","kūnqǔ","곤곡"],["分泌","fēnmì","분비하다"],["季风","jìfēng","계절풍"]],"tr":["경극은 후이극, 한극, 곤곡 등 여러 전통극의 정수를 하나로 합친 것으로, 지금까지 200여 년의 역사를 지니고 있다.","현지 정부와 환경 보호 자원봉사자들이 함께 노력한 덕분에, 말라 가던 바이양뎬 호수에 다시 푸른 물결이 일렁이게 되었다.","사람은 잠자는 동안 성장 호르몬을 많이 분비하므로, 충분한 수면은 청소년의 성장에 특히 중요하다.","오랫동안 계절풍의 영향을 받아, 우리나라 동부 지역은 여름에 덥고 비가 많으며 겨울에 춥고 건조하다."],"ow":[[["徽剧","huījù","후이극(안후이 지방극)"],["昆曲","kūnqǔ","곤곡"]],[["濒临","bīnlín","~에 처하다, 직면하다"],["干涸","gānhé","(물이) 말라붙다"],["白洋淀","Báiyáng Diàn","바이양뎬(호수)"],["碧波荡漾","bì bō dàng yàng","푸른 물결이 일렁이다"],["环保","huánbǎo","환경 보호"]],[["分泌","fēnmì","분비하다"],["激素","jīsù","호르몬"],["发育","fāyù","발육하다"],["尤为","yóuwéi","특히"]],[["季风","jìfēng","계절풍"],["干燥","gānzào","건조하다"]]]},{"o":["北宋画家张择端的《清明上河图》生动地再现了汴京繁华的市井生活。","研究表明，经常阅读纸质书的人，往往比只看电子屏幕的人更能长时间保持专注。","鉴于近期多地出现极端天气，气象部门提醒市民尽量减少不必要的外出。","由于长期过度放牧和盲目开垦，令内蒙古部分草原出现了严重的沙化现象。"],"a":3,"type":"주어 결여","why":"“由于…，令…” 때문에 “出现”의 주어가 없다. 令을 빼면 “草原”이 주어가 된다.","fix":"由于长期过度放牧和盲目开垦，内蒙古部分草原出现了严重的沙化现象。","words":[["开垦","kāikěn","개간하다"],["沙化","shāhuà","사막화"],["张择端","Zhāng Zéduān","장택단(화가)"],["汴京","Biànjīng","변경(북송의 수도)"],["市井","shìjǐng","저잣거리"],["鉴于","jiànyú","~을 감안하여"],["专注力","zhuānzhùlì","집중력"]],"tr":["북송 화가 장택단의 「청명상하도」는 변경의 번화한 저잣거리 생활을 생생하게 재현했다.","연구에 따르면 종이책을 자주 읽는 사람은 전자 화면만 보는 사람보다 대체로 더 오래 집중을 유지할 수 있다.","최근 여러 지역에 극단적인 날씨가 나타난 점을 감안해, 기상 당국은 시민들에게 불필요한 외출을 되도록 줄이라고 당부했다.","오랜 과잉 방목과 무분별한 개간으로 내몽골 일부 초원에 심각한 사막화가 나타났다."],"ow":[[["张择端","Zhāng Zéduān","장택단(화가)"],["汴京","Biànjīng","변경(북송의 수도)"],["市井","shìjǐng","저잣거리"]],[["纸质","zhǐzhì","종이로 된"],["专注","zhuānzhù","집중하다"]],[["鉴于","jiànyú","~을 감안하여"],["极端","jíduān","극단적인"],["外出","wàichū","외출하다"]],[["开垦","kāikěn","개간하다"],["沙化","shāhuà","사막화"]]]},{"o":["针对部分游客在黄山景区随意投喂野生猕猴的现象，景区管理部门近日又一套更为严格的管理办法。","沙棘根系发达，耐旱耐寒，是西北地区防风固沙、保持水土的理想树种。","宋代的瓷器以造型简约、釉色温润著称，其中汝窑的天青色瓷器尤为珍贵。","能否合理安排时间，在很大程度上决定了一个人的工作效率。"],"a":0,"type":"술어 결여","why":"“又一套…办法”에 동사가 없다. “出台了” 같은 술어가 빠졌다.","fix":"针对部分游客在黄山景区随意投喂野生猕猴的现象，景区管理部门近日又出台了一套更为严格的管理办法。","words":[["猕猴","míhóu","원숭이(붉은털원숭이)"],["投喂","tóuwèi","먹이를 주다"],["沙棘","shājí","산자나무"],["防风固沙","fáng fēng gù shā","바람을 막고 모래를 고정하다"],["釉色","yòusè","유약 빛깔"],["温润","wēnrùn","부드럽고 윤기 있다"],["汝窑","Rǔyáo","여요(송대 가마)"]],"tr":["일부 관광객이 황산 관광지에서 야생 원숭이에게 함부로 먹이를 주는 현상에 대응해, 관광지 관리 부서는 최근 한층 엄격한 관리 방법을 또 내놓았다.","산자나무는 뿌리가 잘 발달하고 가뭄과 추위에 강해, 서북 지역에서 바람과 모래를 막고 흙과 물을 지키는 데 알맞은 나무다.","송나라 자기는 모양이 간결하고 유약 빛깔이 부드러운 것으로 유명하며, 그중에서도 여요의 하늘색 자기가 특히 귀하다.","시간을 합리적으로 배분할 수 있느냐 없느냐가 한 사람의 업무 효율을 상당 부분 결정한다."],"ow":[[["猕猴","míhóu","원숭이(붉은털원숭이)"],["投喂","tóuwèi","먹이를 주다"]],[["沙棘","shājí","산자나무"],["防风固沙","fáng fēng gù shā","바람을 막고 모래를 고정하다"]],[["釉色","yòusè","유약 빛깔"],["温润","wēnrùn","부드럽고 윤기 있다"],["汝窑","Rǔyáo","여요(송대 가마)"],["尤为","yóuwéi","특히"]],[["效率","xiàolǜ","효율"],["程度","chéngdù","정도"],["合理","hélǐ","합리적이다"]]]},{"o":["喀斯特地貌是可溶性岩石长期受水的溶蚀作用而形成的，在广西桂林一带分布尤为广泛。","他虽然年过七旬，却依然坚持每天临摹碑帖，几十年来从未间断。","为了让更多青少年了解中国传统节气文化，这所中学利用课外时间开设的一门名为“二十四节气与农耕”的选修课。","这项调查显示，超过六成的受访者认为，社交媒体在一定程度上加重了他们的孤独感。"],"a":2,"type":"술어 결여","why":"“开设的一门…选修课”는 명사 덩어리라서 문장에 술어가 없다. “开设的”를 “开设了”로 바꿔야 한다.","fix":"为了让更多青少年了解中国传统节气文化，这所中学利用课外时间开设了一门名为“二十四节气与农耕”的选修课。","words":[["节气","jiéqì","절기"],["农耕","nónggēng","농경"],["喀斯特","kāsītè","카르스트"],["溶蚀","róngshí","용식(녹아서 깎임)"],["临摹","línmó","보고 따라 쓰다"],["碑帖","bēitiè","비첩(서예 본보기)"],["间断","jiànduàn","중단되다"]],"tr":["카르스트 지형은 물에 녹는 암석이 오랫동안 물에 녹고 깎여서 생긴 것으로, 광시 구이린 일대에 특히 넓게 분포한다.","그는 일흔이 넘었는데도 여전히 날마다 비첩을 보고 글씨를 따라 쓰며, 수십 년 동안 한 번도 거른 적이 없다.","더 많은 청소년이 중국 전통 절기 문화를 알도록, 이 중학교는 방과 후 시간을 이용해 '24절기와 농경'이라는 선택 과목을 열었다.","이 조사에 따르면 응답자의 60% 이상이 소셜 미디어가 어느 정도 자신의 외로움을 키웠다고 생각한다."],"ow":[[["喀斯特","kāsītè","카르스트"],["溶蚀","róngshí","용식(녹아서 깎임)"],["尤为","yóuwéi","특히"]],[["临摹","línmó","보고 따라 쓰다"],["碑帖","bēitiè","비첩(서예 본보기)"],["间断","jiànduàn","중단되다"],["从未","cóngwèi","한 번도 ~않다"]],[["节气","jiéqì","절기"],["农耕","nónggēng","농경"]],[["社交媒体","shèjiāo méitǐ","소셜 미디어"],["孤独感","gūdúgǎn","외로움"],["受访者","shòufǎngzhě","응답자"],["程度","chéngdù","정도"]]]},{"o":["春秋时期，孔子周游列国十四年，晚年回到鲁国专心整理古代文献。","赫哲族世代聚居在松花江、黑龙江和乌苏里江沿岸，素以用鱼皮缝制衣物的独特技艺闻名。","华南虎是中国特有的虎亚种，野外种群已多年未见踪迹，处境十分危急。","这次大规模的科学考察，为人们深入了解可可西里无人区的地质构造和气候特征。"],"a":3,"type":"술어 결여","why":"“为人们…” 뒤에 “提供了…资料” 같은 술어 부분이 없어 문장이 끝나지 않았다.","fix":"这次大规模的科学考察，为人们深入了解可可西里无人区的地质构造和气候特征提供了宝贵的资料。","words":[["可可西里","Kěkěxīlǐ","커커시리"],["地质构造","dìzhì gòuzào","지질 구조"],["周游列国","zhōu yóu liè guó","여러 나라를 돌아다니다"],["亚种","yàzhǒng","아종"],["踪迹","zōngjì","자취"],["赫哲族","Hèzhézú","허저족"],["聚居","jùjū","모여 살다"],["乌苏里江","Wūsūlǐ Jiāng","우수리강"]],"tr":["춘추 시대에 공자는 14년 동안 여러 나라를 돌아다니다가, 말년에 노나라로 돌아와 옛 문헌 정리에 몰두했다.","허저족은 대대로 쑹화강, 헤이룽강, 우수리강 기슭에 모여 살았으며, 물고기 가죽으로 옷을 지어 입는 독특한 기술로 예로부터 이름나 있다.","남중국호랑이는 중국에만 있는 호랑이 아종으로, 야생 개체는 여러 해째 자취를 볼 수 없어 처지가 매우 위급하다.","이번 대규모 과학 탐사는 사람들이 커커시리 무인 지대의 지질 구조와 기후 특징을 깊이 이해하는 데 귀중한 자료를 제공했다."],"ow":[[["周游列国","zhōu yóu liè guó","여러 나라를 돌아다니다"],["文献","wénxiàn","문헌"],["孔子","Kǒngzǐ","공자"],["鲁国","Lǔguó","노나라"],["春秋","Chūnqiū","춘추(시대·사서)"]],[["赫哲族","Hèzhézú","허저족"],["聚居","jùjū","모여 살다"],["乌苏里江","Wūsūlǐ Jiāng","우수리강"],["技艺","jìyì","기예, 기술"],["沿岸","yán'àn","연안"]],[["亚种","yàzhǒng","아종"],["踪迹","zōngjì","자취"]],[["可可西里","Kěkěxīlǐ","커커시리"],["地质构造","dìzhì gòuzào","지질 구조"],["考察","kǎochá","탐사하다"]]]},{"o":["大理白族的扎染以板蓝根等植物为染料，图案古朴典雅，至今仍保留着纯手工的制作工序。","新建成的雅鲁藏布大峡谷观测站，大大提高了科研人员获取高原气象数据，为当地的灾害预警赢得了宝贵时间。","福建安溪出产的铁观音经过摇青、杀青、揉捻等多道工序制成，香气馥郁持久。","这部纪录片以细腻的镜头记录了一位老匠人修复古籍的全过程，感动了无数观众。"],"a":1,"type":"목적어 결여","why":"“提高了…获取数据”에서 提高의 목적어가 될 중심어가 없다. “…数据的效率”처럼 중심어를 넣어야 한다.","fix":"新建成的雅鲁藏布大峡谷观测站，大大提高了科研人员获取高原气象数据的效率，为当地的灾害预警赢得了宝贵时间。","words":[["雅鲁藏布大峡谷","Yǎlǔzàngbù Dà Xiágǔ","야루짱부 대협곡"],["古籍","gǔjí","옛 서적"],["白族","Báizú","바이족"],["扎染","zārǎn","홀치기염색"],["板蓝根","bǎnlángēn","판람근(쪽 뿌리)"],["安溪","Ānxī","안시"],["铁观音","tiěguānyīn","철관음(우롱차)"],["馥郁","fùyù","향기가 짙다"]],"tr":["다리 바이족의 홀치기염색은 판람근 같은 식물을 염료로 쓰며, 무늬가 예스럽고 우아하고 지금도 모든 공정을 손으로 한다.","새로 지은 야루짱부 대협곡 관측소는 연구자들이 고원 기상 자료를 얻는 효율을 크게 높여, 현지 재해 경보에 귀중한 시간을 벌어 주었다.","푸젠성 안시에서 나는 철관음은 찻잎 흔들기, 덖기, 비비기 등 여러 공정을 거쳐 만들어지며, 향기가 짙고 오래간다.","이 다큐멘터리는 섬세한 화면으로 한 노장인이 옛 책을 복원하는 전 과정을 기록해 수많은 관객을 감동시켰다."],"ow":[[["白族","Báizú","바이족"],["扎染","zārǎn","홀치기염색"],["板蓝根","bǎnlángēn","판람근(쪽 뿌리)"]],[["雅鲁藏布大峡谷","Yǎlǔzàngbù Dà Xiágǔ","야루짱부 대협곡"],["观测站","guāncèzhàn","관측소"],["预警","yùjǐng","사전 경보"]],[["安溪","Ānxī","안시"],["铁观音","tiěguānyīn","철관음(우롱차)"],["馥郁","fùyù","향기가 짙다"]],[["古籍","gǔjí","옛 서적"],["纪录片","jìlùpiàn","다큐멘터리"],["细腻","xìnì","섬세하다"],["匠人","jiàngrén","장인"],["修复","xiūfù","복원하다"]]]},{"o":["甲骨文是迄今为止中国发现的年代最早的成熟文字系统，距今已有三千多年。","这位年仅二十岁的钢琴家技艺精湛，在肖邦国际钢琴比赛等重要赛事中屡获殊荣。","秦岭作为我国南北方重要的地理分界线，对两侧气候和植被的差异起着关键，被誉为“中华民族的父亲山”。","消费者在网上购物时，往往容易受到商品评价和销量排名的影响。"],"a":2,"type":"목적어 결여","why":"“起着关键” 뒤에 중심어 “作用”이 없다.","fix":"秦岭作为我国南北方重要的地理分界线，对两侧气候和植被的差异起着关键作用，被誉为“中华民族的父亲山”。","words":[["秦岭","Qínlǐng","친링산맥"],["分界线","fēnjièxiàn","경계선"],["植被","zhíbèi","식생"],["甲骨文","jiǎgǔwén","갑골문"],["迄今为止","qì jīn wéi zhǐ","지금까지"],["精湛","jīngzhàn","뛰어나다, 정교하다"],["屡获殊荣","lǚ huò shū róng","여러 번 큰 영예를 얻다"]],"tr":["갑골문은 지금까지 중국에서 발견된 것 가운데 가장 오래된 완성된 문자 체계로, 지금으로부터 3천여 년 전의 것이다.","갓 스무 살인 이 피아니스트는 기량이 뛰어나, 쇼팽 국제 피아노 콩쿠르 같은 주요 대회에서 여러 번 큰 상을 받았다.","친링산맥은 우리나라 남북을 가르는 중요한 지리 경계선으로서 양쪽의 기후와 식생 차이에 결정적인 역할을 하며, '중화민족의 아버지 산'으로 불린다.","소비자는 인터넷 쇼핑을 할 때 상품 후기와 판매 순위에 쉽게 영향을 받는다."],"ow":[[["甲骨文","jiǎgǔwén","갑골문"],["迄今为止","qì jīn wéi zhǐ","지금까지"]],[["精湛","jīngzhàn","뛰어나다, 정교하다"],["屡获殊荣","lǚ huò shū róng","여러 번 큰 영예를 얻다"],["技艺","jìyì","기예, 기술"],["赛事","sàishì","경기, 대회"],["肖邦","Xiāobāng","쇼팽"]],[["秦岭","Qínlǐng","친링산맥"],["分界线","fēnjièxiàn","경계선"],["植被","zhíbèi","식생"]],[["消费者","xiāofèizhě","소비자"],["排名","páimíng","순위"],["销量","xiāoliàng","판매량"]]]},{"o":["长期以来，当地牧民一直保持着与雪豹、岩羊等野生动物和谐共处、互不侵扰的，这在很大程度上得益于藏族传统的生态观念。","茶叶在唐代传入日本，经过长期的发展，逐渐形成了独具特色的日本茶道。","经过几代人的艰苦奋斗，塞罕坝从一片荒原变成了百万亩人工林海。","人工智能技术的迅猛发展，在给生活带来便利的同时，也引发了人们对隐私安全的担忧。"],"a":0,"type":"목적어 결여","why":"“保持着…互不侵扰的” 뒤에 목적어 중심어 “传统”이 없다.","fix":"长期以来，当地牧民一直保持着与雪豹、岩羊等野生动物和谐共处、互不侵扰的传统，这在很大程度上得益于藏族传统的生态观念。","words":[["雪豹","xuěbào","눈표범"],["岩羊","yányáng","바랄(푸른양)"],["侵扰","qīnrǎo","침범해 괴롭히다"],["得益于","déyìyú","~덕분이다"],["茶道","chádào","다도"],["塞罕坝","Sàihǎnbà","싸이한바"],["荒原","huāngyuán","황무지"],["迅猛","xùnměng","빠르고 맹렬하다"]],"tr":["오래전부터 이곳 목축민들은 눈표범, 바랄 같은 야생동물과 서로 해치지 않고 사이좋게 지내 왔는데, 이는 티베트족의 전통 생태관 덕분이 크다.","차는 당나라 때 일본에 전해졌고, 오랜 발전을 거쳐 독특한 일본 다도가 차츰 만들어졌다.","여러 세대에 걸친 고된 노력 끝에, 싸이한바는 황무지에서 백만 무(畝)에 이르는 인공 숲의 바다로 바뀌었다.","인공지능 기술이 빠르게 발전하면서 생활이 편리해졌지만, 동시에 사생활 보호에 대한 걱정도 생겨났다."],"ow":[[["雪豹","xuěbào","눈표범"],["岩羊","yányáng","바랄(푸른양)"],["侵扰","qīnrǎo","침범해 괴롭히다"],["得益于","déyìyú","~덕분이다"],["牧民","mùmín","목축민"],["程度","chéngdù","정도"]],[["茶道","chádào","다도"],["独具特色","dú jù tè sè","독특한 특색을 지니다"]],[["塞罕坝","Sàihǎnbà","싸이한바"],["荒原","huāngyuán","황무지"]],[["迅猛","xùnměng","빠르고 맹렬하다"],["人工智能","réngōng zhìnéng","인공지능"],["隐私","yǐnsī","사생활"],["担忧","dānyōu","걱정"]]]}],[{"o":["黄梅戏唱腔淳朴流畅，表演真切动人，是安徽最具代表性的地方剧种。","位于云南西北部的梅里雪山主峰卡瓦格博海拔约6740米左右，至今仍是一座未被人类登顶的“处女峰”。","不少心理学家认为，童年时期的亲子关系对一个人成年后的性格有着不可忽视的影响。","这座始建于明代的古桥历经数百年风雨，至今依然坚固如初。"],"a":1,"type":"어림수 중복","why":"“约”와 “左右”가 둘 다 어림을 나타내 겹친다. 하나만 써야 한다.","fix":"位于云南西北部的梅里雪山主峰卡瓦格博海拔约6740米，至今仍是一座未被人类登顶的“处女峰”。","words":[["梅里雪山","Méilǐ Xuěshān","메이리 설산"],["卡瓦格博","Kǎwǎgébó","카와거보(봉우리 이름)"],["登顶","dēngdǐng","정상에 오르다"],["唱腔","chàngqiāng","노래 가락"],["淳朴","chúnpǔ","소박하다"],["剧种","jùzhǒng","극의 종류"],["历经","lìjīng","두루 겪다"]],"tr":["황매극은 노래 가락이 소박하고 매끄러우며 연기가 진실하고 감동적이어서, 안후이성을 가장 잘 대표하는 지방극이다.","윈난성 서북부에 있는 메이리 설산의 주봉 카와거보는 해발 약 6,740미터로, 지금까지 아무도 정상에 오르지 못한 '처녀봉'이다.","많은 심리학자는 어린 시절 부모와 자식의 관계가 그 사람이 어른이 된 뒤의 성격에 무시할 수 없는 영향을 준다고 본다.","명나라 때 처음 세워진 이 옛 다리는 수백 년 비바람을 겪고도 지금까지 처음처럼 튼튼하다."],"ow":[[["唱腔","chàngqiāng","노래 가락"],["淳朴","chúnpǔ","소박하다"],["剧种","jùzhǒng","극의 종류"]],[["梅里雪山","Méilǐ Xuěshān","메이리 설산"],["卡瓦格博","Kǎwǎgébó","카와거보(봉우리 이름)"],["登顶","dēngdǐng","정상에 오르다"]],[["不可忽视","bù kě hū shì","무시할 수 없다"],["心理学","xīnlǐxué","심리학"],["亲子","qīnzǐ","부모와 자식"]],[["历经","lìjīng","두루 겪다"],["坚固","jiāngù","튼튼하다"]]]},{"o":["王羲之的《兰亭序》笔势飘逸，被历代书法家奉为“天下第一行书”。","随着远程办公的普及，越来越多的年轻人选择离开一线城市，到生活成本较低的地方定居。","这家博物馆通过数字技术复原了一批已经失传的古代乐器，让观众得以聆听千年前的乐音。","据统计，每年冬季在鄱阳湖越冬的候鸟将近七十多万只，其中不乏白鹤等珍稀物种。"],"a":3,"type":"어림수 중복","why":"“将近”(조금 못 미침)과 “多”(조금 넘음)가 함께 쓰여 뜻이 부딪친다.","fix":"据统计，每年冬季在鄱阳湖越冬的候鸟将近七十万只，其中不乏白鹤等珍稀物种。","words":[["鄱阳湖","Póyáng Hú","포양호"],["越冬","yuèdōng","겨울을 나다"],["不乏","bùfá","적지 않다"],["王羲之","Wáng Xīzhī","왕희지"],["飘逸","piāoyì","시원스럽고 자유롭다"],["失传","shīchuán","전해지지 않게 되다"],["聆听","língtīng","귀 기울여 듣다"]],"tr":["왕희지의 「난정서」는 붓의 기세가 시원스럽고 자유로워, 역대 서예가들에게 '천하제일 행서'로 받들어졌다.","원격 근무가 널리 퍼지면서, 대도시를 떠나 생활비가 덜 드는 곳에 정착하는 젊은이가 점점 늘고 있다.","이 박물관은 디지털 기술로 전해지지 않던 옛 악기들을 복원해, 관람객이 천 년 전의 소리를 들을 수 있게 했다.","통계에 따르면 해마다 겨울 포양호에서 겨울을 나는 철새는 70만 마리에 가까우며, 그중에는 시베리아흰두루미 같은 희귀종도 적지 않다."],"ow":[[["王羲之","Wáng Xīzhī","왕희지"],["飘逸","piāoyì","시원스럽고 자유롭다"]],[["远程办公","yuǎnchéng bàngōng","원격 근무"],["普及","pǔjí","보급되다"],["定居","dìngjū","정착하다"]],[["失传","shīchuán","전해지지 않게 되다"],["聆听","língtīng","귀 기울여 듣다"]],[["鄱阳湖","Póyáng Hú","포양호"],["越冬","yuèdōng","겨울을 나다"],["不乏","bùfá","적지 않다"],["珍稀物种","zhēnxī wùzhǒng","희귀종"]]]},{"o":["由于受地形影响，天山南北两麓的降水量差别悬殊很大，因而形成了截然不同的自然景观。","端午节吃粽子、赛龙舟的习俗由来已久，相传与纪念屈原有关。","这位老教授毕生致力于古文字研究，为后人留下了大量宝贵的学术成果。","在信息爆炸的时代，如何从海量资讯中甄别出真实可靠的内容，成了每个人都要面对的课题。"],"a":0,"type":"뜻 중복","why":"“悬殊”가 이미 ‘차이가 매우 크다’는 뜻이라 “很大”가 군더더기다.","fix":"由于受地形影响，天山南北两麓的降水量相差悬殊，因而形成了截然不同的自然景观。","words":[["麓","lù","산기슭"],["悬殊","xuánshū","차이가 크다"],["截然不同","jié rán bù tóng","완전히 다르다"],["由来已久","yóu lái yǐ jiǔ","유래가 오래되다"],["屈原","Qū Yuán","굴원"],["毕生","bìshēng","평생"],["甄别","zhēnbié","가려내다"]],"tr":["지형의 영향으로 톈산 남쪽과 북쪽 기슭은 강수량 차이가 매우 커서, 전혀 다른 자연 경관이 만들어졌다.","단오에 쭝쯔를 먹고 용선 경주를 하는 풍습은 유래가 오래되었으며, 굴원을 기리는 것과 관련이 있다고 전해진다.","이 노교수는 평생 고문자 연구에 힘써 후세에 귀중한 학술 성과를 많이 남겼다.","정보가 넘쳐 나는 시대에 방대한 정보 속에서 참되고 믿을 만한 내용을 어떻게 가려낼지는 누구나 마주해야 할 과제가 되었다."],"ow":[[["麓","lù","산기슭"],["悬殊","xuánshū","차이가 크다"],["截然不同","jié rán bù tóng","완전히 다르다"]],[["由来已久","yóu lái yǐ jiǔ","유래가 오래되다"],["屈原","Qū Yuán","굴원"]],[["毕生","bìshēng","평생"],["致力于","zhìlì yú","~에 힘쓰다"],["学术","xuéshù","학술"]],[["甄别","zhēnbié","가려내다"],["信息爆炸","xìnxī bàozhà","정보 폭발"],["海量","hǎiliàng","방대한 양"],["资讯","zīxùn","정보"],["课题","kètí","과제"],["可靠","kěkào","믿을 만하다"]]]},{"o":["绍兴是一座有着两千五百多年建城史的江南水乡，素有“东方威尼斯”之称。","有些人表面上看起来自信满满，内心深处却常常怀疑自己的能力。","这项工程的主要目的是为了把长江中下游的富余水量调往干旱缺水的华北地区。","黄土高原土质疏松，植被稀少，一遇暴雨便极易造成严重的水土流失。"],"a":2,"type":"뜻 중복","why":"“目的”와 “为了”가 같은 뜻을 두 번 말한다. “目的是…”만 쓰면 된다.","fix":"这项工程的主要目的是把长江中下游的富余水量调往干旱缺水的华北地区。","words":[["富余","fùyu","남아돌다"],["绍兴","Shàoxīng","사오싱"],["素有","sùyǒu","예로부터 ~라 불리다"],["威尼斯","Wēinísī","베네치아"],["疏松","shūsōng","푸석하다"],["水土流失","shuǐ tǔ liú shī","토양 유실"]],"tr":["사오싱은 2,500여 년의 도시 역사를 지닌 강남의 물의 고장으로, 예로부터 '동양의 베네치아'라고 불려 왔다.","어떤 사람은 겉으로는 자신감이 넘쳐 보여도 마음속 깊은 곳에서는 늘 자기 능력을 의심한다.","이 공사의 주된 목적은 창장강 중하류의 남는 물을 가물고 물이 부족한 화베이 지역으로 보내는 것이다.","황토고원은 흙이 푸석하고 식생이 드물어, 폭우가 한 번 오면 심각한 토양 유실이 일어나기 쉽다."],"ow":[[["绍兴","Shàoxīng","사오싱"],["素有","sùyǒu","예로부터 ~라 불리다"],["威尼斯","Wēinísī","베네치아"],["江南","Jiāngnán","강남(창장강 이남)"]],[["内心深处","nèixīn shēnchù","마음 깊은 곳"],["自信满满","zìxìn mǎnmǎn","자신감이 넘치다"],["怀疑","huáiyí","의심하다"]],[["富余","fùyu","남아돌다"],["中下游","zhōngxiàyóu","중하류"],["干旱","gānhàn","가물다"]],[["疏松","shūsōng","푸석하다"],["水土流失","shuǐ tǔ liú shī","토양 유실"]]]},{"o":["元代画家黄公望晚年隐居富春江畔，历时数年才完成了传世名作《富春山居图》。","专家指出，近年来长江江豚数量回升的主要原因，是全面实施禁渔措施的缘故。","不少企业开始尝试四天工作制，希望以此提升员工的工作积极性和幸福感。","蜂鸟每秒能振翅五十次以上，因而可以像直升机一样在空中悬停。"],"a":1,"type":"뜻 중복","why":"“原因是…”와 “…的缘故”가 같은 뜻이라 겹친다.","fix":"专家指出，近年来长江江豚数量回升的主要原因，是全面实施了禁渔措施。","words":[["江豚","jiāngtún","상괭이(장강 돌고래)"],["禁渔","jìnyú","어로 금지"],["缘故","yuángù","까닭"],["黄公望","Huáng Gōngwàng","황공망"],["隐居","yǐnjū","은거하다"],["蜂鸟","fēngniǎo","벌새"],["悬停","xuántíng","공중에 멈춰 떠 있다"]],"tr":["원나라 화가 황공망은 말년에 푸춘강 가에 은거하며 여러 해에 걸쳐 명작 「부춘산거도」를 완성했다.","전문가들은 최근 창장강 상괭이 수가 다시 늘어난 주된 까닭이 어로 금지 조치를 전면 시행한 데 있다고 분석했다.","많은 기업이 주 4일 근무제를 시도하기 시작했는데, 이를 통해 직원의 업무 의욕과 행복감을 높이려는 것이다.","벌새는 1초에 날개를 50번 넘게 칠 수 있어서 헬리콥터처럼 공중에 멈춰 떠 있을 수 있다."],"ow":[[["黄公望","Huáng Gōngwàng","황공망"],["隐居","yǐnjū","은거하다"]],[["江豚","jiāngtún","상괭이(장강 돌고래)"],["禁渔","jìnyú","어로 금지"],["缘故","yuángù","까닭"]],[["积极性","jījíxìng","의욕"],["尝试","chángshì","시도하다"]],[["蜂鸟","fēngniǎo","벌새"],["悬停","xuántíng","공중에 멈춰 떠 있다"]]]},{"o":["《本草纲目》是明代医学家李时珍历时二十七年编撰而成的药学巨著。","古人常说“疾风知劲草”，越是在逆境中，越能看出一个人的意志是否坚定。","位于四川的九寨沟以翠海、叠瀑和彩林闻名于世，被列入《世界遗产名录》。","为了追求产量，一些农户过量滥用化肥和农药，导致土壤板结、地下水受到污染。"],"a":3,"type":"뜻 중복","why":"“滥用”에 이미 ‘지나치게 함부로 쓰다’는 뜻이 있어 “过量”이 겹친다.","fix":"为了追求产量，一些农户滥用化肥和农药，导致土壤板结、地下水受到污染。","words":[["滥用","lànyòng","남용하다"],["板结","bǎnjié","(흙이) 굳어지다"],["本草纲目","Běncǎo Gāngmù","본초강목"],["李时珍","Lǐ Shízhēn","이시진"],["编撰","biānzhuàn","편찬하다"],["逆境","nìjìng","역경"],["九寨沟","Jiǔzhàigōu","주자이거우"],["叠瀑","diépù","층층 폭포"]],"tr":["「본초강목」은 명나라 의학자 이시진이 27년에 걸쳐 편찬한 약학의 대작이다.","옛사람들은 '거센 바람이 불어야 강한 풀을 안다'고 했는데, 어려운 처지일수록 그 사람의 의지가 굳은지를 더 잘 알 수 있다.","쓰촨성의 주자이거우는 비취빛 호수, 층층 폭포, 오색 숲으로 세계에 이름나 「세계유산 목록」에 올랐다.","생산량을 늘리려고 일부 농가가 화학 비료와 농약을 마구 써서, 흙이 굳고 지하수가 오염되었다."],"ow":[[["本草纲目","Běncǎo Gāngmù","본초강목"],["李时珍","Lǐ Shízhēn","이시진"],["编撰","biānzhuàn","편찬하다"]],[["逆境","nìjìng","역경"],["疾风知劲草","jí fēng zhī jìng cǎo","거센 바람에 강한 풀을 안다"],["意志","yìzhì","의지"]],[["九寨沟","Jiǔzhàigōu","주자이거우"],["叠瀑","diépù","층층 폭포"]],[["滥用","lànyòng","남용하다"],["板结","bǎnjié","(흙이) 굳어지다"]]]},{"o":["凡是参与过罗布泊科学考察的所有队员，都对那片荒凉而神秘的土地怀有深厚的感情。","喜马拉雅山脉是由印度板块与亚欧板块相互碰撞挤压而隆起形成的。","宋词按风格大致可分为婉约派和豪放派，苏轼和辛弃疾是豪放派的代表人物。","过度依赖导航软件，可能会使人的空间记忆能力逐渐退化。"],"a":0,"type":"군더더기","why":"“凡是”가 이미 ‘모두’라는 뜻이라 “所有”가 군더더기다.","fix":"凡是参与过罗布泊科学考察的队员，都对那片荒凉而神秘的土地怀有深厚的感情。","words":[["罗布泊","Luóbù Pō","뤄부포(호수 터)"],["荒凉","huāngliáng","황량하다"],["板块","bǎnkuài","(지각) 판"],["隆起","lóngqǐ","솟아오르다"],["婉约","wǎnyuē","부드럽고 완곡하다"],["豪放","háofàng","호방하다"],["辛弃疾","Xīn Qìjí","신기질"],["退化","tuìhuà","퇴화하다"]],"tr":["뤄부포 과학 탐사에 참여했던 대원들은 모두 그 황량하고 신비로운 땅에 깊은 애정을 품고 있다.","히말라야산맥은 인도판과 유라시아판이 서로 부딪쳐 밀어붙이면서 솟아올라 생긴 것이다.","송사는 풍격에 따라 크게 완약파와 호방파로 나뉘며, 소식과 신기질이 호방파의 대표 인물이다.","내비게이션 앱에 지나치게 기대면 사람의 공간 기억 능력이 차츰 퇴화할 수 있다."],"ow":[[["罗布泊","Luóbù Pō","뤄부포(호수 터)"],["荒凉","huāngliáng","황량하다"],["考察","kǎochá","탐사하다"]],[["板块","bǎnkuài","(지각) 판"],["隆起","lóngqǐ","솟아오르다"]],[["婉约","wǎnyuē","부드럽고 완곡하다"],["豪放","háofàng","호방하다"],["辛弃疾","Xīn Qìjí","신기질"]],[["退化","tuìhuà","퇴화하다"],["依赖","yīlài","의존하다"],["导航","dǎoháng","내비게이션"]]]},{"o":["活字印刷术由北宋的毕昇发明，比德国人谷登堡发明的金属活字印刷早了约四百年。","一个人能否在职场中走得长远，不仅取决于专业能力，还取决于沟通与合作的能力。","西双版纳热带雨林中已记录的高等植物多达五千余种之多，约占全国总数的六分之一。","每到深秋，北京香山漫山遍野的黄栌叶由绿转红，吸引了大批游客前来观赏。"],"a":2,"type":"군더더기","why":"“多达”와 “之多”가 같은 강조를 두 번 한다. 하나만 쓴다.","fix":"西双版纳热带雨林中已记录的高等植物多达五千余种，约占全国总数的六分之一。","words":[["西双版纳","Xīshuāngbǎnnà","시솽반나"],["雨林","yǔlín","우림"],["活字印刷术","huózì yìnshuāshù","활자 인쇄술"],["毕昇","Bì Shēng","필승(인물)"],["职场","zhíchǎng","직장"],["漫山遍野","màn shān biàn yě","온 산과 들에 가득하다"],["黄栌","huánglú","안개나무"]],"tr":["활자 인쇄술은 북송의 필승이 발명했는데, 독일의 구텐베르크가 발명한 금속 활자 인쇄보다 약 400년 앞선다.","한 사람이 직장에서 오래 잘 나아갈 수 있을지는 전문 능력뿐 아니라 소통과 협력 능력에도 달려 있다.","시솽반나 열대 우림에서 지금까지 기록된 고등 식물은 5천여 종에 이르며, 전국 전체의 약 6분의 1을 차지한다.","늦가을이 되면 베이징 샹산의 온 산을 덮은 안개나무 잎이 초록에서 붉은색으로 바뀌어 많은 관광객이 구경하러 온다."],"ow":[[["活字印刷术","huózì yìnshuāshù","활자 인쇄술"],["毕昇","Bì Shēng","필승(인물)"],["谷登堡","Gǔdēngbǎo","구텐베르크"]],[["职场","zhíchǎng","직장"],["取决于","qǔjué yú","~에 달려 있다"]],[["西双版纳","Xīshuāngbǎnnà","시솽반나"],["雨林","yǔlín","우림"]],[["漫山遍野","màn shān biàn yě","온 산과 들에 가득하다"],["黄栌","huánglú","안개나무"]]]},{"o":["秦始皇统一六国后，推行“书同文、车同轨”，促进了各地的经济文化交流。","尽管这款新药的临床试验效果良好，但它是否存在长期副作用仍有待进一步观察。","每逢涨潮，钱塘江口的潮水便如万马奔腾，汹涌而来，蔚为壮观。","据国家林业和草原局近日发布的公告称，我国境内野生东北虎的数量较二十年前已有明显增长。"],"a":3,"type":"군더더기","why":"“据…”(~에 따르면)와 “…称”(~라고 밝혔다)이 같은 뜻을 두 번 말한다.","fix":"据国家林业和草原局近日发布的公告，我国境内野生东北虎的数量较二十年前已有明显增长。","words":[["东北虎","Dōngběihǔ","시베리아호랑이"],["书同文、车同轨","shū tóng wén, chē tóng guǐ","문자와 수레바퀴 폭을 통일함"],["临床","línchuáng","임상"],["副作用","fùzuòyòng","부작용"],["钱塘江","Qiántáng Jiāng","첸탕강"],["汹涌","xiōngyǒng","세차게 솟구치다"],["蔚为壮观","wèi wéi zhuàng guān","장관을 이루다"]],"tr":["진시황은 여섯 나라를 통일한 뒤 '문자와 수레바퀴 폭의 통일'을 시행해 각 지역의 경제·문화 교류를 촉진했다.","이 신약은 임상 시험 효과가 좋았지만, 장기적인 부작용이 있는지는 더 지켜봐야 한다.","밀물 때마다 첸탕강 하구의 조수는 만 마리 말이 달리듯 세차게 밀려와 장관을 이룬다.","국가임업초원국이 최근 발표한 공고에 따르면, 우리나라 안의 야생 시베리아호랑이 수가 20년 전보다 뚜렷하게 늘었다."],"ow":[[["书同文、车同轨","shū tóng wén, chē tóng guǐ","문자와 수레바퀴 폭을 통일함"],["秦始皇","Qínshǐhuáng","진시황"],["推行","tuīxíng","시행하다"]],[["临床","línchuáng","임상"],["副作用","fùzuòyòng","부작용"]],[["钱塘江","Qiántáng Jiāng","첸탕강"],["汹涌","xiōngyǒng","세차게 솟구치다"],["蔚为壮观","wèi wéi zhuàng guān","장관을 이루다"]],[["东北虎","Dōngběihǔ","시베리아호랑이"],["公告","gōnggào","공고"]]]},{"o":["黄河流经宁夏、内蒙古一带时形成了一个巨大的“几”字形弯道，河套平原就位于这里。","研讨会上，来自海峡两岸的考古学者彼此互相交流了近年来在良渚遗址研究方面的最新发现。","明代郑和率领庞大的船队七下西洋，最远到达了非洲东海岸和红海沿岸。","面对批评，与其急于辩解，不如先冷静地反思自己是否真的有不足之处。"],"a":1,"type":"군더더기","why":"“彼此”와 “互相”이 모두 ‘서로’라는 뜻이라 겹친다.","fix":"研讨会上，来自海峡两岸的考古学者互相交流了近年来在良渚遗址研究方面的最新发现。","words":[["良渚","Liángzhǔ","량주"],["遗址","yízhǐ","유적"],["河套平原","Hétào Píngyuán","허타오 평원"],["郑和","Zhèng Hé","정화"],["西洋","Xīyáng","서양(인도양 일대)"],["辩解","biànjiě","변명하다"],["反思","fǎnsī","돌이켜 반성하다"]],"tr":["황허강은 닝샤와 내몽골 일대를 흐르면서 '几' 자 모양의 큰 굽이를 이루는데, 허타오 평원이 바로 여기에 있다.","학술 토론회에서 양안의 고고학자들이 최근 량주 유적 연구에서 얻은 새로운 발견을 서로 나누었다.","명나라 정화는 큰 선단을 이끌고 일곱 차례 서양으로 나아가, 멀리 아프리카 동해안과 홍해 연안까지 이르렀다.","비판을 받았을 때는 서둘러 변명하기보다 먼저 차분하게 자신에게 정말 부족한 점이 있는지 돌아보는 편이 낫다."],"ow":[[["河套平原","Hétào Píngyuán","허타오 평원"],["弯道","wāndào","굽이"],["宁夏","Níngxià","닝샤"]],[["良渚","Liángzhǔ","량주"],["遗址","yízhǐ","유적"]],[["郑和","Zhèng Hé","정화"],["西洋","Xīyáng","서양(인도양 일대)"],["沿岸","yán'àn","연안"],["红海","Hóng Hǎi","홍해"],["东海","Dōng Hǎi","동중국해"]],[["辩解","biànjiě","변명하다"],["反思","fǎnsī","돌이켜 반성하다"]]]}],[{"o":["苗族银饰工艺繁复，造型精美，承载着这个民族古老的历史记忆。","睡前长时间使用手机，屏幕发出的蓝光会抑制人体内褪黑素的生成，进而影响睡眠质量。","保护区工作人员多年来坚持走村入户开展宣传，有效增强了陕西洋县村民保护朱鹮的知识。","杭州西湖三面环山，湖中分布着苏堤、白堤和三潭印月等著名景观。"],"a":2,"type":"동사–목적어","why":"“增强”은 “意识” 같은 말과 어울리고 “知识”와는 어울리지 않는다.","fix":"保护区工作人员多年来坚持走村入户开展宣传，有效增强了陕西洋县村民保护朱鹮的意识。","words":[["朱鹮","zhūhuán","따오기"],["走村入户","zǒu cūn rù hù","마을과 집을 찾아다니다"],["银饰","yínshì","은 장신구"],["繁复","fánfù","복잡하다"],["承载","chéngzài","싣다, 담다"],["抑制","yìzhì","억제하다"],["褪黑素","tuìhēisù","멜라토닌"]],"tr":["먀오족의 은 장신구는 만드는 과정이 복잡하고 모양이 정교하며, 이 민족의 오랜 역사 기억을 담고 있다.","자기 전에 휴대폰을 오래 쓰면 화면의 블루라이트가 몸속 멜라토닌 생성을 억제해 수면의 질에 영향을 준다.","보호구역 직원들은 여러 해 동안 마을과 집을 찾아다니며 홍보를 해, 산시성 양현 주민들의 따오기 보호 의식을 효과적으로 높였다.","항저우 시후는 세 면이 산으로 둘러싸여 있고, 호수 안에는 쑤디, 바이디, 싼탄인웨 같은 이름난 명소가 있다."],"ow":[[["银饰","yínshì","은 장신구"],["繁复","fánfù","복잡하다"],["承载","chéngzài","싣다, 담다"]],[["抑制","yìzhì","억제하다"],["褪黑素","tuìhēisù","멜라토닌"]],[["朱鹮","zhūhuán","따오기"],["走村入户","zǒu cūn rù hù","마을과 집을 찾아다니다"]],[["三潭印月","Sān Tán Yìn Yuè","싼탄인웨(명소)"],["苏堤","Sū Dī","쑤디(제방)"]]]},{"o":["许多家长认为，让孩子学习古琴不仅能陶冶孩子的观察能力，还能使他们更深入地了解传统文化。","每年农历六月二十四前后，凉山彝族同胞都会点燃火把，举行盛大的火把节，以祈求五谷丰登。","徐霞客用三十多年的时间游历了大半个中国，写下了地理名著《徐霞客游记》。","生物多样性的丧失不仅会破坏生态平衡，最终也将威胁到人类自身的生存。"],"a":0,"type":"동사–목적어","why":"“陶冶”는 “情操·性情”과 어울리고 “观察能力”와는 어울리지 않는다.","fix":"许多家长认为，让孩子学习古琴不仅能陶冶孩子的情操，还能使他们更深入地了解传统文化。","words":[["古琴","gǔqín","고금(칠현금)"],["陶冶","táoyě","(품성을) 기르다"],["徐霞客","Xú Xiákè","서하객"],["游历","yóulì","두루 여행하다"],["生物多样性","shēngwù duōyàngxìng","생물 다양성"],["凉山","Liángshān","량산"],["彝族","Yízú","이족"],["火把节","Huǒbǎ Jié","횃불 축제"]],"tr":["많은 부모는 아이에게 고금을 배우게 하면 관찰력을 기를 수 있을 뿐 아니라 전통문화도 더 깊이 이해하게 된다고 생각한다.","해마다 음력 6월 24일 무렵이면 량산의 이족 사람들은 횃불을 밝히고 성대한 횃불 축제를 열어 오곡의 풍년을 빈다.","서하객은 30여 년 동안 중국 땅의 절반 이상을 두루 여행하며 지리 명저 「서하객유기」를 남겼다.","생물 다양성이 사라지면 생태 균형이 깨질 뿐 아니라, 결국 인류 자신의 생존까지 위협받게 된다."],"ow":[[["古琴","gǔqín","고금(칠현금)"],["陶冶","táoyě","(품성을) 기르다"]],[["凉山","Liángshān","량산"],["彝族","Yízú","이족"],["火把节","Huǒbǎ Jié","횃불 축제"]],[["徐霞客","Xú Xiákè","서하객"],["游历","yóulì","두루 여행하다"]],[["生物多样性","shēngwù duōyàngxìng","생물 다양성"],["丧失","sàngshī","잃다"],["威胁","wēixié","위협하다"],["平衡","pínghéng","균형을 맞추다"]]]},{"o":["中国古代的四大发明对世界文明的进步产生了不可估量的影响。","小提琴家在演奏这首协奏曲时，将乐曲中缠绵悱恻的情感表现得淋漓尽致。","长白山天池是一座火山口湖，湖面海拔两千一百多米，是中朝两国的界湖。","面对数十年不遇的严重干旱，滇中地区的基层干部日夜奋战在抗旱一线，终于完成了数十万群众的饮水问题。"],"a":3,"type":"동사–목적어","why":"“问题”는 “解决”과 어울린다. “完成…问题”는 동사와 목적어가 맞지 않는다.","fix":"面对数十年不遇的严重干旱，滇中地区的基层干部日夜奋战在抗旱一线，终于解决了数十万群众的饮水问题。","words":[["滇中","Diān zhōng","윈난 중부"],["奋战","fènzhàn","분투하다"],["不可估量","bù kě gū liàng","헤아릴 수 없다"],["协奏曲","xiézòuqǔ","협주곡"],["缠绵悱恻","chán mián fěi cè","애절하다"],["淋漓尽致","lín lí jìn zhì","남김없이 드러내다"],["火山口湖","huǒshānkǒu hú","화구호"]],"tr":["중국 고대의 4대 발명은 세계 문명의 발전에 헤아릴 수 없는 영향을 주었다.","바이올리니스트는 이 협주곡을 연주하면서 곡에 담긴 애절한 감정을 남김없이 표현해 냈다.","창바이산 톈츠는 화구호로, 수면이 해발 2,100여 미터에 있으며 중국과 북한의 경계를 이루는 호수다.","수십 년 만의 극심한 가뭄 앞에서 윈난 중부의 현장 간부들은 밤낮없이 가뭄 대응에 매달려, 마침내 수십만 주민의 식수 문제를 해결했다."],"ow":[[["不可估量","bù kě gū liàng","헤아릴 수 없다"],["四大发明","sì dà fāmíng","4대 발명"]],[["协奏曲","xiézòuqǔ","협주곡"],["缠绵悱恻","chán mián fěi cè","애절하다"],["淋漓尽致","lín lí jìn zhì","남김없이 드러내다"]],[["火山口湖","huǒshānkǒu hú","화구호"],["天池","Tiānchí","톈츠(천지)"],["界湖","jièhú","국경 호수"]],[["滇中","Diān zhōng","윈난 중부"],["奋战","fènzhàn","분투하다"],["干旱","gānhàn","가물다"]]]},{"o":["《红楼梦》以贾、史、王、薛四大家族的兴衰为背景，展现了封建社会的种种矛盾。","随着保护力度的不断加大，鄂尔多斯遗鸥繁殖地的生态环境近年来得到了显著的增加。","尽管面临原材料价格上涨的压力，这家老字号依然坚持手工制作，从不偷工减料。","珠江三角洲河网密布，土地肥沃，自古以来就是富庶的鱼米之乡。"],"a":1,"type":"주어–술어","why":"주어 “生态环境”은 “增加”와 어울리지 않는다. “改善”이 맞다.","fix":"随着保护力度的不断加大，鄂尔多斯遗鸥繁殖地的生态环境近年来得到了显著的改善。","words":[["鄂尔多斯","È'ěrduōsī","오르도스"],["遗鸥","yí'ōu","고비갈매기"],["兴衰","xīngshuāi","흥망성쇠"],["封建","fēngjiàn","봉건"],["老字号","lǎozìhao","오래된 이름난 가게"],["偷工减料","tōu gōng jiǎn liào","일손과 재료를 속이다"],["富庶","fùshù","풍요롭다"]],"tr":["「홍루몽」은 가·사·왕·설 네 가문의 흥망을 배경으로 봉건 사회의 여러 모순을 보여 준다.","보호가 계속 강화되면서, 오르도스의 고비갈매기 번식지 생태 환경은 최근 몇 년 사이 크게 좋아졌다.","원재료 값이 오르는 부담 속에서도 이 오래된 가게는 여전히 손으로 만드는 방식을 지키며 재료나 일손을 속인 적이 없다.","주장강 삼각주는 물길이 촘촘하고 땅이 기름져, 예로부터 물산이 풍부한 고장이었다."],"ow":[[["兴衰","xīngshuāi","흥망성쇠"],["封建","fēngjiàn","봉건"]],[["鄂尔多斯","È'ěrduōsī","오르도스"],["遗鸥","yí'ōu","고비갈매기"],["繁殖","fánzhí","번식하다"]],[["老字号","lǎozìhao","오래된 이름난 가게"],["偷工减料","tōu gōng jiǎn liào","일손과 재료를 속이다"]],[["富庶","fùshù","풍요롭다"],["珠江三角洲","Zhūjiāng Sānjiǎozhōu","주장강 삼각주"],["鱼米之乡","yú mǐ zhī xiāng","물산이 풍부한 고장"],["肥沃","féiwò","비옥하다"]]]},{"o":["无锡惠山泥人造型饱满、色彩明快，其中以憨态可掬的“阿福”形象最为人们所熟知。","这位作家笔下的乡村生活质朴而温馨，唤起了许多读者对童年的回忆。","南宋时期，商品经济空前繁荣，都城临安的人口急剧扩大，夜市和瓦舍遍布全城。","云南元阳的哈尼梯田依山而建，层层叠叠，是哈尼族人世代耕耘的结晶。"],"a":2,"type":"주어–술어","why":"주어 “人口”는 “扩大”와 어울리지 않는다. “增加·增长”이 맞다.","fix":"南宋时期，商品经济空前繁荣，都城临安的人口急剧增加，夜市和瓦舍遍布全城。","words":[["临安","Lín'ān","임안(남송 수도)"],["瓦舍","wǎshè","와사(송대 공연장)"],["质朴","zhìpǔ","소박하다"],["哈尼梯田","Hāní tītián","하니족 계단식 논"],["耕耘","gēngyún","땅을 갈고 김매다"],["结晶","jiéjīng","결정(성과)"],["惠山泥人","Huìshān nírén","후이산 진흙 인형"],["饱满","bǎomǎn","통통하고 꽉 차다"]],"tr":["우시의 후이산 진흙 인형은 모양이 통통하고 색이 밝으며, 그중에서도 천진하고 귀여운 '아푸'가 가장 널리 알려져 있다.","이 작가가 그린 시골 생활은 소박하고 따뜻해, 많은 독자에게 어린 시절의 기억을 불러일으켰다.","남송 시대에는 상업이 전에 없이 번성해, 도읍 임안의 인구가 크게 늘고 야시장과 공연장이 도시 곳곳에 퍼졌다.","윈난 위안양의 하니족 계단식 논은 산을 따라 층층이 만들어진 것으로, 하니족이 대대로 땅을 일구어 온 결실이다."],"ow":[[["惠山泥人","Huìshān nírén","후이산 진흙 인형"],["饱满","bǎomǎn","통통하고 꽉 차다"]],[["质朴","zhìpǔ","소박하다"],["唤起","huànqǐ","불러일으키다"],["温馨","wēnxīn","따뜻하다"]],[["临安","Lín'ān","임안(남송 수도)"],["瓦舍","wǎshè","와사(송대 공연장)"]],[["哈尼梯田","Hāní tītián","하니족 계단식 논"],["耕耘","gēngyún","땅을 갈고 김매다"],["结晶","jiéjīng","결정(성과)"]]]},{"o":["中医养生讲究“治未病”，其核心理念是在疾病发生之前就通过调理饮食和作息来增强体质的方法。","隶书的出现是汉字发展史上的一次重大变革，它使汉字的书写变得更加简便。","不少城市推出“十五分钟生活圈”，让居民步行一刻钟就能满足日常的基本需求。","研究人员发现，海豚在睡眠时大脑的两个半球会轮流休息，以便随时保持警觉。"],"a":0,"type":"주어–목적어","why":"“理念是…方法”이 되어 주어 “理念”과 목적어 “方法”이 맞지 않는다.","fix":"中医养生讲究“治未病”，其核心理念是在疾病发生之前就通过调理饮食和作息来增强体质。","words":[["治未病","zhìwèibìng","병이 나기 전에 다스리다"],["调理","tiáolǐ","조절하다"],["作息","zuòxī","일과 휴식"],["体质","tǐzhì","체질"],["隶书","lìshū","예서"],["变革","biàngé","변혁"],["海豚","hǎitún","돌고래"],["警觉","jǐngjué","경계심"]],"tr":["중의학의 양생은 '병이 나기 전에 다스리기'를 중시하며, 그 핵심은 병이 생기기 전에 식사와 생활 리듬을 조절해 체질을 튼튼히 하는 것이다.","예서의 등장은 한자 발전사에서 큰 변혁으로, 한자를 쓰기가 더 간편해졌다.","많은 도시가 '15분 생활권'을 내세워, 주민이 걸어서 15분 안에 일상의 기본 필요를 채울 수 있게 했다.","연구자들은 돌고래가 잠잘 때 뇌의 두 반구가 번갈아 쉬어서 언제든 경계를 늦추지 않는다는 것을 발견했다."],"ow":[[["治未病","zhìwèibìng","병이 나기 전에 다스리다"],["调理","tiáolǐ","조절하다"],["作息","zuòxī","일과 휴식"],["体质","tǐzhì","체질"],["饮食","yǐnshí","음식, 식사"]],[["隶书","lìshū","예서"],["变革","biàngé","변혁"],["重大","zhòngdà","중대하다"]],[["生活圈","shēnghuóquān","생활권"],["一刻钟","yíkèzhōng","15분"]],[["海豚","hǎitún","돌고래"],["警觉","jǐngjué","경계심"]]]},{"o":["京杭大运河北起北京，南达杭州，贯通了海河、黄河、淮河、长江和钱塘江五大水系。","适当的挫折能让孩子学会面对失败，从而培养出更为坚韧的性格。","这款国产大型客机的成功首飞，标志着我国已具备自主研制干线飞机的能力。","张家界独特的砂岩峰林地貌，是数亿年来海洋沉积、地壳抬升和流水侵蚀共同作用的地方。"],"a":3,"type":"주어–목적어","why":"“地貌是…地方”이 되어 주어와 목적어가 맞지 않는다. “…的结果”가 맞다.","fix":"张家界独特的砂岩峰林地貌，是数亿年来海洋沉积、地壳抬升和流水侵蚀共同作用的结果。","words":[["张家界","Zhāngjiājiè","장자제"],["砂岩","shāyán","사암"],["峰林","fēnglín","봉우리 숲"],["沉积","chénjī","퇴적"],["地壳","dìqiào","지각"],["侵蚀","qīnshí","침식"],["坚韧","jiānrèn","강인하다"],["标志","biāozhì","상징하다, 나타내다"]],"tr":["징항 대운하는 북쪽 베이징에서 남쪽 항저우까지 이어지며 하이허, 황허, 화이허, 창장, 첸탕강의 5대 수계를 꿰뚫는다.","적당한 좌절은 아이가 실패를 마주하는 법을 배우게 해, 더 강인한 성격을 길러 준다.","이 국산 대형 여객기의 첫 비행 성공은 우리나라가 간선 여객기를 스스로 개발할 능력을 갖추었음을 보여 준다.","장자제의 독특한 사암 봉우리 숲 지형은 수억 년 동안 바다의 퇴적, 지각의 융기, 물의 침식이 함께 작용해 만들어진 것이다."],"ow":[[["贯通","guàntōng","꿰뚫다"],["水系","shuǐxì","수계"]],[["坚韧","jiānrèn","강인하다"],["挫折","cuòzhé","좌절"]],[["标志","biāozhì","상징하다, 나타내다"],["研制","yánzhì","연구 제작하다"],["首飞","shǒufēi","첫 비행"]],[["张家界","Zhāngjiājiè","장자제"],["砂岩","shāyán","사암"],["峰林","fēnglín","봉우리 숲"],["沉积","chénjī","퇴적"],["地壳","dìqiào","지각"],["侵蚀","qīnshí","침식"]]]},{"o":["王昭君出塞和亲的故事流传千古，成为历代文人墨客吟咏的题材。","能否控制好入湖污染物的排放，是滇池水质持续好转的重要保证。","这份报告的数据来源是否可靠，直接关系到最终结论的可信度。","喜马拉雅旱獭常常在洞口直立张望，一旦发现危险，便发出尖锐的叫声提醒同伴。"],"a":1,"type":"양면–한면","why":"앞은 “能否”(되느냐 안 되느냐) 양면인데 뒤는 “好转的保证” 한쪽 면뿐이라 맞지 않는다.","fix":"控制好入湖污染物的排放，是滇池水质持续好转的重要保证。","words":[["滇池","Diān Chí","뎬츠호"],["王昭君","Wáng Zhāojūn","왕소군"],["出塞","chūsài","변방으로 나가다"],["和亲","héqīn","화친(혼인 동맹)"],["文人墨客","wén rén mò kè","문인과 묵객"],["吟咏","yínyǒng","읊다"],["旱獭","hàntǎ","마멋"]],"tr":["왕소군이 변방으로 시집가 화친을 이룬 이야기는 오랫동안 전해져, 역대 문인들이 즐겨 읊는 소재가 되었다.","호수로 들어가는 오염 물질 배출을 잘 통제하느냐가 뎬츠호 수질이 계속 좋아지는 중요한 보장이다.","이 보고서의 자료 출처가 믿을 만한지는 최종 결론의 신뢰도와 직접 관계된다.","히말라야마멋은 굴 입구에 곧게 서서 주위를 살피다가, 위험을 발견하면 날카로운 소리를 내어 동료에게 알린다."],"ow":[[["王昭君","Wáng Zhāojūn","왕소군"],["出塞","chūsài","변방으로 나가다"],["和亲","héqīn","화친(혼인 동맹)"],["文人墨客","wén rén mò kè","문인과 묵객"],["吟咏","yínyǒng","읊다"]],[["滇池","Diān Chí","뎬츠호"],["排放","páifàng","배출하다"]],[["可信度","kěxìndù","신뢰도"],["可靠","kěkào","믿을 만하다"]],[["旱獭","hàntǎ","마멋"],["张望","zhāngwàng","두리번거리다"],["尖锐","jiānruì","날카롭다"]]]},{"o":["武夷岩茶品质的好坏，在很大程度上得益于武夷山独特的丹霞地貌和湿润多雾的气候。","唐太宗善于纳谏，任用贤能，开创了历史上政治清明、经济繁荣的“贞观之治”。","研究显示，长期处于噪声环境中的人，更容易出现注意力下降和情绪烦躁等问题。","这项技术能否大规模推广，还取决于其生产成本能否进一步降低。"],"a":0,"type":"양면–한면","why":"“好坏”는 양면인데 “得益于”(덕을 보다)는 좋은 쪽 한 면만 말한다.","fix":"武夷岩茶品质优异，在很大程度上得益于武夷山独特的丹霞地貌和湿润多雾的气候。","words":[["武夷岩茶","Wǔyí yánchá","우이 암차"],["得益于","déyìyú","~덕을 보다"],["丹霞地貌","dānxiá dìmào","단샤 지형"],["唐太宗","Táng Tàizōng","당 태종"],["纳谏","nàjiàn","간언을 받아들이다"],["贞观之治","Zhēnguān zhī zhì","정관의 치"],["烦躁","fánzào","초조하다"]],"tr":["우이 암차의 품질이 좋은 것은 상당 부분 우이산의 독특한 단샤 지형과 습하고 안개 많은 기후 덕분이다.","당 태종은 신하의 직언을 잘 받아들이고 인재를 등용해, 정치가 깨끗하고 경제가 번영한 '정관의 치'를 열었다.","연구에 따르면 오랫동안 소음 속에 있는 사람은 주의력 저하와 짜증 같은 문제가 생기기 쉽다.","이 기술을 대규모로 보급할 수 있을지는 생산 비용을 더 낮출 수 있느냐에도 달려 있다."],"ow":[[["武夷岩茶","Wǔyí yánchá","우이 암차"],["得益于","déyìyú","~덕을 보다"],["丹霞地貌","dānxiá dìmào","단샤 지형"],["程度","chéngdù","정도"]],[["唐太宗","Táng Tàizōng","당 태종"],["纳谏","nàjiàn","간언을 받아들이다"],["贞观之治","Zhēnguān zhī zhì","정관의 치"],["任用贤能","rèn yòng xián néng","인재를 등용하다"]],[["烦躁","fánzào","초조하다"],["噪声","zàoshēng","소음"]],[["取决于","qǔjué yú","~에 달려 있다"],["推广","tuīguǎng","널리 보급하다"]]]},{"o":["《诗经》是中国最早的一部诗歌总集，收录了西周初年至春秋中叶的诗歌三百零五篇。","越来越多的消费者在选购家电时，把节能环保作为重要的考量因素。","近年来，贵州草海通过退耕还湿、清理围网等措施，明显改善了黑颈鹤的栖息环境和种群数量。","由于纬度较高，冬季的哈尔滨白昼短暂，下午四点多天色便已暗了下来。"],"a":2,"type":"목적어 일부 불일치","why":"“改善”은 “栖息环境”과는 맞지만 “种群数量”과는 맞지 않는다. 수는 “增加”해야 한다.","fix":"近年来，贵州草海通过退耕还湿、清理围网等措施，明显改善了黑颈鹤的栖息环境，增加了其种群数量。","words":[["草海","Cǎo Hǎi","차오하이(호수)"],["退耕还湿","tuì gēng huán shī","농지를 습지로 되돌리다"],["黑颈鹤","hēijǐnghè","검은목두루미"],["栖息","qīxī","서식하다"],["诗经","Shījīng","시경"],["中叶","zhōngyè","중엽"],["纬度","wěidù","위도"],["白昼","báizhòu","낮"]],"tr":["「시경」은 중국 최초의 시가 총집으로, 서주 초기부터 춘추 중엽까지의 시 305편을 싣고 있다.","가전제품을 고를 때 에너지 절약과 친환경을 중요한 고려 요소로 삼는 소비자가 늘고 있다.","최근 구이저우 차오하이는 농지를 습지로 되돌리고 그물 양식장을 걷어 내는 등의 조치로 검은목두루미의 서식 환경을 개선하고 개체 수를 늘렸다.","위도가 높아서 겨울 하얼빈은 낮이 짧아, 오후 4시가 조금 넘으면 벌써 날이 어두워진다."],"ow":[[["诗经","Shījīng","시경"],["中叶","zhōngyè","중엽"],["春秋","Chūnqiū","춘추(시대·사서)"]],[["消费者","xiāofèizhě","소비자"],["考量","kǎoliáng","고려"],["节能","jiénéng","에너지 절약"],["环保","huánbǎo","환경 보호"]],[["草海","Cǎo Hǎi","차오하이(호수)"],["退耕还湿","tuì gēng huán shī","농지를 습지로 되돌리다"],["黑颈鹤","hēijǐnghè","검은목두루미"],["栖息","qīxī","서식하다"]],[["纬度","wěidù","위도"],["白昼","báizhòu","낮"]]]}],[{"o":["苏轼一生仕途坎坷，屡遭贬谪，却始终保持着乐观豁达的人生态度。","研究人员在实验中发现，即使是轻度脱水，也会使人的认知能力有所下降。","每年四月，洱海边的海菜花竞相开放，洁白的花朵点缀在碧绿的水面上。","由于缺乏有效监管，生长在悬崖峭壁上的野生铁皮石斛被采药人已经挖得所剩无几，如今只在少数偏远山区还能偶尔见到。"],"a":3,"type":"부사 위치","why":"부사 “已经”은 “被” 구 앞에 와야 한다. “被采药人已经挖”는 어순이 틀렸다.","fix":"由于缺乏有效监管，生长在悬崖峭壁上的野生铁皮石斛已经被采药人挖得所剩无几，如今只在少数偏远山区还能偶尔见到。","words":[["悬崖峭壁","xuán yá qiào bì","깎아지른 절벽"],["铁皮石斛","tiěpí shíhú","철피석곡(약초)"],["所剩无几","suǒ shèng wú jǐ","남은 것이 거의 없다"],["仕途","shìtú","벼슬길"],["坎坷","kǎnkě","순탄치 않다"],["贬谪","biǎnzhé","좌천되다"],["豁达","huòdá","너그럽고 활달하다"],["洱海","Ěr Hǎi","얼하이"]],"tr":["소식은 평생 벼슬길이 험난해 여러 번 좌천되었지만, 늘 낙천적이고 너그러운 삶의 태도를 지켰다.","연구자들은 실험에서 가벼운 탈수만으로도 사람의 인지 능력이 어느 정도 떨어진다는 것을 발견했다.","해마다 4월이면 얼하이 호숫가의 하이차이화가 앞다투어 피어나, 새하얀 꽃이 초록 물 위를 수놓는다.","제대로 된 관리 감독이 없어서, 깎아지른 절벽에 자라는 야생 철피석곡은 약초꾼들에게 거의 다 캐여 이제는 몇몇 외진 산간에서나 가끔 볼 수 있다."],"ow":[[["仕途","shìtú","벼슬길"],["坎坷","kǎnkě","순탄치 않다"],["贬谪","biǎnzhé","좌천되다"],["豁达","huòdá","너그럽고 활달하다"]],[["脱水","tuōshuǐ","탈수"],["认知","rènzhī","인지"]],[["洱海","Ěr Hǎi","얼하이"],["海菜花","hǎicàihuā","하이차이화(수생 식물)"],["竞相","jìngxiāng","앞다투어"],["点缀","diǎnzhuì","꾸미다, 수놓다"]],[["悬崖峭壁","xuán yá qiào bì","깎아지른 절벽"],["铁皮石斛","tiěpí shíhú","철피석곡(약초)"],["所剩无几","suǒ shèng wú jǐ","남은 것이 거의 없다"],["偏远","piānyuǎn","외지다"]]]},{"o":["塔克拉玛干沙漠是中国面积最大的沙漠，被人们称为“死亡之海”。","许多外国游客很对中国的书法和篆刻艺术感兴趣，常常专程到杭州的西泠印社参观学习。","汉代的丝绸之路东起长安，西达地中海沿岸，是连接东西方文明的重要通道。","他宁可多花些时间反复核对，也不愿意因为一时疏忽而给团队带来损失。"],"a":1,"type":"부사 위치","why":"정도부사 “很”은 “感兴趣” 바로 앞에 와야 한다. “对…很感兴趣”가 맞다.","fix":"许多外国游客对中国的书法和篆刻艺术很感兴趣，常常专程到杭州的西泠印社参观学习。","words":[["篆刻","zhuànkè","전각"],["专程","zhuānchéng","일부러 찾아가다"],["西泠印社","Xīlíng Yìnshè","서령인사"],["塔克拉玛干沙漠","Tǎkèlāmǎgān Shāmò","타클라마칸 사막"],["丝绸之路","Sīchóu zhī Lù","실크로드"],["地中海","Dìzhōng Hǎi","지중해"],["疏忽","shūhu","소홀히 하다"]],"tr":["타클라마칸 사막은 중국에서 가장 넓은 사막으로, 사람들에게 '죽음의 바다'라고 불린다.","많은 외국인 관광객이 중국의 서예와 전각 예술에 큰 관심을 보이며, 일부러 항저우의 서령인사를 찾아가 배우곤 한다.","한나라의 실크로드는 동쪽 장안에서 서쪽 지중해 연안까지 이어진, 동서양 문명을 잇는 중요한 길이었다.","그는 차라리 시간을 더 들여 몇 번이고 확인할지언정, 한순간의 부주의로 팀에 손해를 끼치려 하지 않는다."],"ow":[[["塔克拉玛干沙漠","Tǎkèlāmǎgān Shāmò","타클라마칸 사막"],["死亡之海","sǐwáng zhī hǎi","죽음의 바다"]],[["篆刻","zhuànkè","전각"],["专程","zhuānchéng","일부러 찾아가다"],["西泠印社","Xīlíng Yìnshè","서령인사"]],[["丝绸之路","Sīchóu zhī Lù","실크로드"],["地中海","Dìzhōng Hǎi","지중해"],["沿岸","yán'àn","연안"],["通道","tōngdào","통로"]],[["疏忽","shūhu","소홀히 하다"],["宁可","nìngkě","차라리"],["核对","héduì","대조 확인하다"],["团队","tuánduì","팀"]]]},{"o":["福州出产的寿山石质地晶莹、色泽丰富，历来被视为雕刻印章和工艺摆件的上乘材料。","心理学家发现，人们往往高估自己做出正确判断的能力，这种现象被称为“过度自信”。","由于山洪冲毁了道路，救援人员把滞留在峡谷中的两百多名游客至今仍没有全部转移到安全地带。","寒武纪生命大爆发时期，地球上的生物种类在短短数百万年内迅速增加。"],"a":2,"type":"부정사 위치","why":"부정어 “没有”와 부사 “至今仍”은 “把” 앞에 와야 한다.","fix":"由于山洪冲毁了道路，救援人员至今仍没有把滞留在峡谷中的两百多名游客全部转移到安全地带。","words":[["山洪","shānhóng","산사태성 홍수"],["滞留","zhìliú","발이 묶이다"],["峡谷","xiágǔ","협곡"],["高估","gāogū","과대평가하다"],["寒武纪","Hánwǔjì","캄브리아기"],["寿山石","Shòushān shí","서우산석"],["晶莹","jīngyíng","맑고 투명하다"],["摆件","bǎijiàn","장식품"]],"tr":["푸저우에서 나는 서우산석은 맑고 투명하며 빛깔이 다양해, 예로부터 도장과 공예 장식품을 새기는 최상급 재료로 여겨졌다.","심리학자들은 사람들이 흔히 자기의 올바른 판단 능력을 과대평가한다는 것을 발견했는데, 이를 '과잉 확신'이라고 한다.","산사태성 홍수로 길이 끊겨, 구조대는 협곡에 발이 묶인 관광객 200여 명을 아직까지 모두 안전한 곳으로 옮기지 못했다.","캄브리아기 생명 대폭발 시기에 지구의 생물 종류는 불과 수백만 년 사이에 빠르게 늘어났다."],"ow":[[["寿山石","Shòushān shí","서우산석"],["晶莹","jīngyíng","맑고 투명하다"],["摆件","bǎijiàn","장식품"]],[["高估","gāogū","과대평가하다"],["过度自信","guòdù zìxìn","과잉 확신"],["心理学","xīnlǐxué","심리학"]],[["山洪","shānhóng","산사태성 홍수"],["滞留","zhìliú","발이 묶이다"],["峡谷","xiágǔ","협곡"]],[["寒武纪","Hánwǔjì","캄브리아기"],["生命大爆发","shēngmìng dà bàofā","생명 대폭발"],["物种","wùzhǒng","생물 종"]]]},{"o":["这位老中医行医五十余年，向患者从来没有多收过一分钱诊费。","长江三峡西起重庆奉节的白帝城，东至湖北宜昌的南津关，全长约一百九十三公里。","据说人类的嗅觉能分辨上万种不同的气味，但能用语言准确描述的却寥寥无几。","大熊猫虽然属于食肉目，但它们的食物中百分之九十九以上都是竹子。"],"a":0,"type":"개사구 위치","why":"부사 “从来没有”는 개사구 “向患者” 앞에 와야 한다.","fix":"这位老中医行医五十余年，从来没有向患者多收过一分钱诊费。","words":[["行医","xíngyī","의사로 일하다"],["诊费","zhěnfèi","진료비"],["三峡","Sānxiá","싼샤(삼협)"],["白帝城","Báidì Chéng","백제성"],["嗅觉","xiùjué","후각"],["寥寥无几","liáo liáo wú jǐ","매우 적다"],["食肉目","shíròumù","식육목"]],"tr":["이 노한의사는 50여 년 동안 진료하면서 환자에게 진료비를 한 푼도 더 받은 적이 없다.","창장 싼샤는 서쪽 충칭 펑제의 백제성에서 동쪽 후베이 이창의 난진관까지, 전체 길이가 약 193킬로미터다.","사람의 후각은 만 가지가 넘는 냄새를 구별할 수 있다고 하지만, 말로 정확히 설명할 수 있는 것은 아주 적다.","대왕판다는 식육목에 속하지만 먹이의 99% 이상이 대나무다."],"ow":[[["行医","xíngyī","의사로 일하다"],["诊费","zhěnfèi","진료비"],["患者","huànzhě","환자"]],[["三峡","Sānxiá","싼샤(삼협)"],["白帝城","Báidì Chéng","백제성"]],[["嗅觉","xiùjué","후각"],["寥寥无几","liáo liáo wú jǐ","매우 적다"]],[["食肉目","shíròumù","식육목"],["大熊猫","dàxióngmāo","대왕판다"]]]},{"o":["古代的科举制度为寒门子弟提供了通过读书改变命运的途径。","这家公司推出的翻译软件能够在离线状态下识别并翻译四十多种语言。","位于湖北的神农架林区植被茂密，是我国中部地区重要的生物基因库。","各地自然保护区根据不同物种的生活习性应该制定有针对性的保护方案。"],"a":3,"type":"개사구 위치","why":"조동사 “应该”는 개사구 “根据…” 앞에 와야 한다.","fix":"各地自然保护区应该根据不同物种的生活习性制定有针对性的保护方案。","words":[["习性","xíxìng","습성"],["针对性","zhēnduìxìng","맞춤성"],["科举","kējǔ","과거 제도"],["寒门","hánmén","가난한 집안"],["离线","líxiàn","오프라인"],["神农架","Shénnóngjià","선눙자"],["茂密","màomì","무성하다"],["基因库","jīyīnkù","유전자 은행"]],"tr":["옛 과거 제도는 가난한 집안의 자제들에게 공부로 운명을 바꿀 길을 열어 주었다.","이 회사가 내놓은 번역 앱은 오프라인 상태에서도 40여 개 언어를 알아듣고 번역할 수 있다.","후베이성의 선눙자 임구는 숲이 무성해, 우리나라 중부 지역의 중요한 생물 유전자 보고다.","각지의 자연보호구역은 종마다 다른 생활 습성에 따라 맞춤형 보호 방안을 세워야 한다."],"ow":[[["科举","kējǔ","과거 제도"],["寒门","hánmén","가난한 집안"]],[["离线","líxiàn","오프라인"],["识别","shíbié","식별하다"]],[["神农架","Shénnóngjià","선눙자"],["茂密","màomì","무성하다"],["基因库","jīyīnkù","유전자 은행"]],[["习性","xíxìng","습성"],["针对性","zhēnduìxìng","맞춤성"],["物种","wùzhǒng","생물 종"]]]},{"o":["她用了整整三年时间，把这部长达百万字的古典小说翻译成了西班牙语。","科研人员在浙江天目山的一处密林中发现了珍稀的三株野生红豆杉，树龄均在五百年以上。","研究表明，经常和家人一起吃饭的孩子，在语言表达方面往往比独自用餐的孩子表现得更好。","中国古代建筑多采用榫卯结构，不用一根钉子就能使木构件牢固地连接在一起。"],"a":1,"type":"관형어 순서","why":"수량사 “三株”는 형용사 “珍稀的”보다 앞에 와야 한다.","fix":"科研人员在浙江天目山的一处密林中发现了三株珍稀的野生红豆杉，树龄均在五百年以上。","words":[["天目山","Tiānmù Shān","톈무산"],["密林","mìlín","울창한 숲"],["红豆杉","hóngdòushān","주목"],["树龄","shùlíng","나무 나이"],["古典","gǔdiǎn","고전"],["榫卯","sǔnmǎo","장부 이음"],["构件","gòujiàn","부재, 부품"]],"tr":["그녀는 꼬박 3년을 들여 백만 자에 이르는 이 고전 소설을 스페인어로 옮겼다.","연구진은 저장성 톈무산의 한 울창한 숲에서 희귀한 야생 주목 세 그루를 발견했는데, 나무 나이가 모두 500년이 넘었다.","연구에 따르면 가족과 자주 함께 밥을 먹는 아이는 혼자 먹는 아이보다 언어 표현에서 대체로 더 뛰어나다.","중국 옛 건축은 대부분 장부 이음 구조를 써서, 못 하나 없이도 나무 부재를 단단히 이을 수 있다."],"ow":[[["古典","gǔdiǎn","고전"],["西班牙语","Xībānyáyǔ","스페인어"]],[["天目山","Tiānmù Shān","톈무산"],["密林","mìlín","울창한 숲"],["红豆杉","hóngdòushān","주목"],["树龄","shùlíng","나무 나이"],["珍稀","zhēnxī","진귀하고 드물다"]],[["独自","dúzì","혼자"],["用餐","yòngcān","식사하다"]],[["榫卯","sǔnmǎo","장부 이음"],["构件","gòujiàn","부재, 부품"]]]},{"o":["黄河携带的泥沙在入海口不断淤积，使河口三角洲的面积逐年扩大。","他的小说语言朴素，却往往能在平淡的叙述中揭示出深刻的人生道理。","上世纪三十年代，一位著名的我国植物学家曾徒步深入高黎贡山，采集了数千份珍贵标本。","不少家长担心，孩子过早接触电子游戏会影响学习，但也有专家认为适度游戏能锻炼反应能力。"],"a":2,"type":"관형어 순서","why":"소속을 나타내는 “我国”은 “一位著名的”보다 앞에 와야 한다.","fix":"上世纪三十年代，我国一位著名的植物学家曾徒步深入高黎贡山，采集了数千份珍贵标本。","words":[["高黎贡山","Gāolígòng Shān","가오리궁산"],["徒步","túbù","걸어서"],["标本","biāoběn","표본"],["淤积","yūjī","퇴적되다"],["三角洲","sānjiǎozhōu","삼각주"],["叙述","xùshù","서술"],["揭示","jiēshì","드러내 보이다"]],"tr":["황허강이 싣고 온 진흙과 모래가 하구에 계속 쌓여, 하구 삼각주의 면적이 해마다 넓어진다.","그의 소설은 문장이 소박하지만, 평범한 서술 속에서 깊은 삶의 이치를 드러내곤 한다.","1930년대에 우리나라의 한 유명한 식물학자가 걸어서 가오리궁산 깊숙이 들어가 귀중한 표본 수천 점을 채집했다.","많은 부모는 아이가 너무 일찍 게임을 접하면 공부에 지장이 있을까 걱정하지만, 적당한 게임이 반응 능력을 길러 준다고 보는 전문가도 있다."],"ow":[[["淤积","yūjī","퇴적되다"],["三角洲","sānjiǎozhōu","삼각주"]],[["叙述","xùshù","서술"],["揭示","jiēshì","드러내 보이다"]],[["高黎贡山","Gāolígòng Shān","가오리궁산"],["徒步","túbù","걸어서"],["标本","biāoběn","표본"]],[["电子游戏","diànzǐ yóuxì","게임"],["适度","shìdù","적당하다"],["接触","jiēchù","접하다"]]]},{"o":["湖北省博物馆珍藏着一套青铜的气势恢宏的战国编钟，出土两千多年后仍能演奏出完整的乐曲。","青海湖每年夏季都会迎来大批斑头雁、棕头鸥等候鸟在湖心岛上繁衍生息。","珊瑚礁虽然占海洋面积不到百分之一，却为约四分之一的海洋生物提供了生存空间。","心理学研究发现，人们越是追求完美，就越容易对自己产生不满和自责的情绪。"],"a":0,"type":"관형어 순서","why":"재료를 나타내는 “青铜”은 중심어 “编钟”에 가장 가깝게 붙어야 한다.","fix":"湖北省博物馆珍藏着一套气势恢宏的战国青铜编钟，出土两千多年后仍能演奏出完整的乐曲。","words":[["编钟","biānzhōng","편종"],["气势恢宏","qì shì huī hóng","기세가 웅장하다"],["战国","Zhànguó","전국 시대"],["出土","chūtǔ","출토되다"],["斑头雁","bāntóuyàn","줄기러기"],["繁衍生息","fán yǎn shēng xī","번식하며 살아가다"],["珊瑚礁","shānhújiāo","산호초"]],"tr":["후베이성 박물관에는 기세가 웅장한 전국 시대 청동 편종 한 벌이 소장되어 있는데, 출토된 지 2천여 년이 지나도 온전한 곡을 연주할 수 있다.","칭하이호에는 해마다 여름이면 줄기러기, 갈색머리갈매기 같은 철새가 많이 찾아와 호수 가운데 섬에서 번식하며 산다.","산호초는 바다 면적의 1%도 차지하지 않지만, 바다 생물의 약 4분의 1에게 살 곳을 제공한다.","심리학 연구에 따르면 사람은 완벽을 추구할수록 자신에게 불만과 자책을 느끼기 쉽다."],"ow":[[["编钟","biānzhōng","편종"],["气势恢宏","qì shì huī hóng","기세가 웅장하다"],["战国","Zhànguó","전국 시대"],["出土","chūtǔ","출토되다"]],[["斑头雁","bāntóuyàn","줄기러기"],["繁衍生息","fán yǎn shēng xī","번식하며 살아가다"]],[["珊瑚礁","shānhújiāo","산호초"],["海洋生物","hǎiyáng shēngwù","해양 생물"],["生存空间","shēngcún kōngjiān","살아갈 공간"]],[["追求完美","zhuīqiú wánměi","완벽을 추구하다"],["心理学","xīnlǐxué","심리학"],["自责","zìzé","자책"]]]},{"o":["李白的诗想象奇特、气势磅礴，充满浪漫主义色彩，被后人称为“诗仙”。","经过多年的摸索，科研团队终于解决并发现了制约这种濒危植物人工繁育的关键问题。","大量研究证实，长期坚持有氧运动可以有效降低患心血管疾病的风险。","这些古老的船型屋是黎族先民为适应海南湿热多雨的气候而建造的。"],"a":1,"type":"나열 순서","why":"문제는 먼저 “发现”하고 나서 “解决”한다. 순서가 뒤바뀌었다.","fix":"经过多年的摸索，科研团队终于发现并解决了制约这种濒危植物人工繁育的关键问题。","words":[["摸索","mōsuǒ","모색하다"],["制约","zhìyuē","제약하다"],["濒危","bīnwēi","멸종 위기의"],["繁育","fányù","번식시키다"],["磅礴","pángbó","웅장하다"],["心血管","xīnxuèguǎn","심혈관"],["黎族","Lízú","리족"],["先民","xiānmín","선조"]],"tr":["이백의 시는 상상력이 기발하고 기세가 웅장하며 낭만주의 색채가 가득해, 후세에 '시선'으로 불렸다.","여러 해의 모색 끝에 연구팀은 마침내 이 멸종 위기 식물의 인공 번식을 가로막는 핵심 문제를 찾아내 해결했다.","많은 연구에서 꾸준한 유산소 운동이 심혈관 질환에 걸릴 위험을 효과적으로 낮춘다는 것이 입증되었다.","이 오래된 배 모양 집은 리족 선조들이 하이난의 덥고 습하며 비 많은 기후에 맞추어 지은 것이다."],"ow":[[["磅礴","pángbó","웅장하다"],["浪漫主义","làngmàn zhǔyì","낭만주의"],["诗仙","shīxiān","시선(시의 신선)"]],[["摸索","mōsuǒ","모색하다"],["制约","zhìyuē","제약하다"],["濒危","bīnwēi","멸종 위기의"],["繁育","fányù","번식시키다"],["团队","tuánduì","팀"]],[["心血管","xīnxuèguǎn","심혈관"],["有氧运动","yǒuyǎng yùndòng","유산소 운동"],["证实","zhèngshí","입증하다"]],[["黎族","Lízú","리족"],["先民","xiānmín","선조"]]]},{"o":["秋冬时节，大批大天鹅从西伯利亚飞抵山东荣成的海湾，在这里度过漫长的冬季。","尽管这家餐馆位置偏僻，门口却每天都排着长长的队伍。","地震发生时，如果身处高楼，千万不要乘坐电梯逃生，而应迅速躲到坚固的家具旁边。","考古人员先对这座西汉墓葬进行了发掘和清理，然后才对墓葬周边区域展开初步勘探，以确定墓葬的具体位置。"],"a":3,"type":"나열 순서","why":"위치를 확인하는 “勘探”이 먼저이고 “发掘”이 나중이어야 한다. 일의 순서가 거꾸로다.","fix":"考古人员先对墓葬周边区域展开初步勘探，确定这座西汉墓葬的具体位置后，再对其进行发掘和清理。","words":[["墓葬","mùzàng","무덤"],["发掘","fājué","발굴하다"],["勘探","kāntàn","탐사하다"],["西伯利亚","Xībólìyà","시베리아"],["荣成","Róngchéng","룽청"],["偏僻","piānpì","외지다"]],"tr":["가을과 겨울이면 많은 큰고니가 시베리아에서 산둥성 룽청의 만으로 날아와 긴 겨울을 보낸다.","이 식당은 자리가 외진데도 문 앞에는 날마다 긴 줄이 늘어선다.","지진이 났을 때 높은 건물 안에 있다면 절대 엘리베이터를 타고 탈출하지 말고, 재빨리 튼튼한 가구 옆으로 몸을 피해야 한다.","고고학자들은 먼저 이 서한 무덤을 발굴하고 정리한 다음에야, 무덤의 정확한 위치를 확인하려고 주변 지역을 처음 탐사했다."],"ow":[[["西伯利亚","Xībólìyà","시베리아"],["荣成","Róngchéng","룽청"]],[["偏僻","piānpì","외지다"],["队伍","duìwu","줄, 행렬"],["餐馆","cānguǎn","식당"]],[["坚固","jiāngù","튼튼하다"],["逃生","táoshēng","탈출하다"]],[["墓葬","mùzàng","무덤"],["发掘","fājué","발굴하다"],["勘探","kāntàn","탐사하다"]]]}],[{"o":["只有当栖息地的生态环境得到整体恢复，野生亚洲象的种群数量就能实现稳定增长。","汉武帝时期，张骞两次出使西域，开辟了中原通往中亚各国的交通要道。","人在情绪低落时，听一段节奏舒缓的音乐往往能起到一定的调节作用。","台湾海峡是连接东海与南海的重要通道，最窄处约一百三十公里。"],"a":0,"type":"짝 오류","why":"“只有”은 “才”와 짝을 이룬다. “就”를 쓰면 틀린다.","fix":"只有当栖息地的生态环境得到整体恢复，野生亚洲象的种群数量才能实现稳定增长。","words":[["亚洲象","Yàzhōu xiàng","아시아코끼리"],["张骞","Zhāng Qiān","장건"],["出使","chūshǐ","사신으로 가다"],["西域","Xīyù","서역"],["中原","Zhōngyuán","중원"],["舒缓","shūhuǎn","느긋하다"],["海峡","hǎixiá","해협"]],"tr":["서식지의 생태 환경이 전체적으로 회복되어야만 야생 아시아코끼리의 개체 수가 꾸준히 늘어날 수 있다.","한 무제 때 장건은 두 번 서역에 사신으로 가서, 중원에서 중앙아시아 여러 나라로 통하는 교통로를 열었다.","기분이 가라앉았을 때 느린 음악을 들으면 대체로 어느 정도 마음을 다스리는 효과가 있다.","타이완 해협은 동중국해와 남중국해를 잇는 중요한 통로로, 가장 좁은 곳은 약 130킬로미터다."],"ow":[[["亚洲象","Yàzhōu xiàng","아시아코끼리"],["栖息地","qīxīdì","서식지"]],[["张骞","Zhāng Qiān","장건"],["出使","chūshǐ","사신으로 가다"],["西域","Xīyù","서역"],["中原","Zhōngyuán","중원"],["汉武帝","Hàn Wǔdì","한 무제"],["中亚","Zhōngyà","중앙아시아"]],[["舒缓","shūhuǎn","느긋하다"],["低落","dīluò","가라앉다"],["调节","tiáojié","조절하다"]],[["海峡","hǎixiá","해협"],["通道","tōngdào","통로"],["东海","Dōng Hǎi","동중국해"]]]},{"o":["京剧脸谱色彩鲜明，红色象征忠勇，白色则多代表奸诈。","浙江金华火腿选用当地特有的“两头乌”猪腌制而成，色泽鲜艳，咸香适口。","漓江两岸奇峰林立，江水清澈，泛舟其上，仿佛置身于一幅流动的山水画中。","无论风雪多么猛烈，驻守在南极长城站的科考队员们坚持每天按时采集和记录气象数据。"],"a":3,"type":"짝 오류","why":"“无论” 뒤에는 “都”가 짝으로 와야 하는데 빠졌다.","fix":"无论风雪多么猛烈，驻守在南极长城站的科考队员们都坚持每天按时采集和记录气象数据。","words":[["驻守","zhùshǒu","주둔하여 지키다"],["长城站","Chángchéng Zhàn","창청 기지"],["脸谱","liǎnpǔ","경극 얼굴 분장"],["奸诈","jiānzhà","간사하다"],["漓江","Lí Jiāng","리장강"],["泛舟","fànzhōu","배를 띄우다"],["金华火腿","Jīnhuá huǒtuǐ","진화 햄"],["腌制","yānzhì","소금에 절이다"]],"tr":["경극의 얼굴 분장은 색이 뚜렷한데, 붉은색은 충성과 용맹을, 흰색은 대개 간사함을 나타낸다.","저장성 진화 햄은 이 지역에만 있는 '양두우' 돼지를 소금에 절여 만드는데, 빛깔이 곱고 짭짤하며 향긋해 입에 잘 맞는다.","리장강 양쪽 기슭에는 기이한 봉우리가 숲처럼 서 있고 강물이 맑아, 배를 띄우면 마치 흐르는 산수화 속에 들어간 듯하다.","눈보라가 아무리 거세도 남극 창청 기지에 머무는 대원들은 날마다 제시간에 기상 자료를 모으고 기록한다."],"ow":[[["脸谱","liǎnpǔ","경극 얼굴 분장"],["奸诈","jiānzhà","간사하다"]],[["金华火腿","Jīnhuá huǒtuǐ","진화 햄"],["腌制","yānzhì","소금에 절이다"]],[["漓江","Lí Jiāng","리장강"],["泛舟","fànzhōu","배를 띄우다"]],[["驻守","zhùshǒu","주둔하여 지키다"],["长城站","Chángchéng Zhàn","창청 기지"]]]},{"o":["泰山古称“岱宗”，被尊为五岳之首，历代帝王多在此举行封禅大典。","即使是经验丰富的登山者，在攀登高海拔雪山时也不敢有丝毫大意。","与其被动地等待政策扶持，宁可主动寻找新的市场机会。","为了避免对野生动物造成干扰，国家公园内的观测活动必须在指定区域进行。"],"a":2,"type":"짝 오류","why":"“与其”은 “不如”와 짝을 이룬다. “宁可”는 “也”와 짝이다.","fix":"与其被动地等待政策扶持，不如主动寻找新的市场机会。","words":[["扶持","fúchí","지원하다"],["岱宗","Dàizōng","대종(태산의 옛 이름)"],["五岳","Wǔyuè","오악"],["封禅","fēngshàn","봉선(하늘에 올리는 제사)"],["丝毫","sīháo","조금도"],["干扰","gānrǎo","방해하다"]],"tr":["태산은 옛 이름이 '대종'으로 오악 가운데 으뜸으로 받들어졌으며, 역대 황제들이 이곳에서 봉선 의식을 많이 치렀다.","경험 많은 등산가라도 높은 설산을 오를 때는 조금도 방심하지 못한다.","정책 지원을 수동적으로 기다리기보다는 스스로 새로운 시장 기회를 찾는 편이 낫다.","야생동물을 방해하지 않도록 국립공원 안의 관찰 활동은 반드시 지정된 구역에서 해야 한다."],"ow":[[["岱宗","Dàizōng","대종(태산의 옛 이름)"],["五岳","Wǔyuè","오악"],["封禅","fēngshàn","봉선(하늘에 올리는 제사)"]],[["丝毫","sīháo","조금도"],["攀登","pāndēng","오르다"],["大意","dàyi","방심하다"]],[["扶持","fúchí","지원하다"],["宁可","nìngkě","차라리"],["被动","bèidòng","수동적이다"]],[["干扰","gānrǎo","방해하다"],["指定","zhǐdìng","지정하다"]]]},{"o":["纳西族的东巴纸以当地一种瑞香科植物的树皮为原料，防虫耐腐，可保存数百年之久。","不但金丝猴是我国特有的珍稀灵长类动物，而且是国家一级重点保护野生动物。","尽管这项实验失败了很多次，研究团队却从未想过放弃。","受温室效应影响，近几十年来全球冰川普遍出现了退缩现象。"],"a":1,"type":"관련사 위치","why":"앞뒤 절의 주어가 같으면 “不但”은 주어 “金丝猴” 뒤에 와야 한다.","fix":"金丝猴不但是我国特有的珍稀灵长类动物，而且是国家一级重点保护野生动物。","words":[["金丝猴","jīnsīhóu","황금원숭이"],["灵长类","língzhǎnglèi","영장류"],["温室效应","wēnshì xiàoyìng","온실 효과"],["退缩","tuìsuō","후퇴하다, 줄어들다"],["纳西族","Nàxīzú","나시족"],["东巴纸","dōngbāzhǐ","둥바 종이"],["瑞香科","ruìxiāngkē","팥꽃나무과"],["耐腐","nàifǔ","잘 썩지 않다"]],"tr":["나시족의 둥바 종이는 이 지역 팥꽃나무과 식물의 껍질로 만드는데, 벌레를 막고 잘 썩지 않아 수백 년 동안 보존할 수 있다.","황금원숭이는 우리나라에만 사는 귀한 영장류일 뿐 아니라, 국가 1급 중점 보호 야생동물이기도 하다.","이 실험은 여러 번 실패했지만, 연구팀은 한 번도 포기하려 하지 않았다.","온실 효과의 영향으로 최근 수십 년 동안 세계 곳곳의 빙하가 대체로 줄어들었다."],"ow":[[["纳西族","Nàxīzú","나시족"],["东巴纸","dōngbāzhǐ","둥바 종이"],["瑞香科","ruìxiāngkē","팥꽃나무과"],["耐腐","nàifǔ","잘 썩지 않다"]],[["金丝猴","jīnsīhóu","황금원숭이"],["灵长类","língzhǎnglèi","영장류"],["珍稀","zhēnxī","진귀하고 드물다"]],[["团队","tuánduì","팀"],["从未","cóngwèi","한 번도 ~않다"]],[["温室效应","wēnshì xiàoyìng","온실 효과"],["退缩","tuìsuō","후퇴하다, 줄어들다"],["冰川","bīngchuān","빙하"]]]},{"o":["虽然额济纳旗地处偏远、交通不便，却每年深秋前来观赏金色胡杨林的摄影爱好者络绎不绝。","春节期间贴春联、放鞭炮的习俗，寄托了人们辞旧迎新、祈求吉祥的美好愿望。","每逢农历三月初三，广西各地的壮族青年男女便会聚在一起对唱山歌，这一习俗被称为“歌圩”。","这家出版社推出的系列丛书，以通俗易懂的语言向孩子们介绍了天文学的基础知识。"],"a":0,"type":"관련사 위치","why":"“却”는 부사라서 뒤 절의 주어 “摄影爱好者” 뒤에 와야 한다.","fix":"虽然额济纳旗地处偏远、交通不便，每年深秋前来观赏金色胡杨林的摄影爱好者却络绎不绝。","words":[["额济纳旗","Éjìnà Qí","어지나기"],["胡杨林","húyánglín","호양나무 숲"],["络绎不绝","luò yì bù jué","끊임없이 이어지다"],["春联","chūnlián","춘련"],["辞旧迎新","cí jiù yíng xīn","묵은해를 보내고 새해를 맞다"],["壮族","Zhuàngzú","좡족"],["对唱","duìchàng","주고받으며 노래하다"],["歌圩","gēxū","거쉬(노래 모임)"]],"tr":["어지나기는 외지고 교통이 불편하지만, 해마다 늦가을이면 황금빛 호양나무 숲을 보러 오는 사진 애호가들의 발길이 끊이지 않는다.","설에 춘련을 붙이고 폭죽을 터뜨리는 풍습에는 묵은해를 보내고 새해를 맞으며 복을 비는 사람들의 바람이 담겨 있다.","해마다 음력 3월 3일이면 광시 곳곳의 좡족 젊은 남녀가 모여 산노래를 주고받는데, 이 풍습을 '거쉬'라고 한다.","이 출판사가 낸 총서는 쉽고 알기 쉬운 말로 아이들에게 천문학의 기초 지식을 소개한다."],"ow":[[["额济纳旗","Éjìnà Qí","어지나기"],["胡杨林","húyánglín","호양나무 숲"],["络绎不绝","luò yì bù jué","끊임없이 이어지다"],["偏远","piānyuǎn","외지다"]],[["春联","chūnlián","춘련"],["辞旧迎新","cí jiù yíng xīn","묵은해를 보내고 새해를 맞다"]],[["壮族","Zhuàngzú","좡족"],["对唱","duìchàng","주고받으며 노래하다"],["歌圩","gēxū","거쉬(노래 모임)"]],[["天文学","tiānwénxué","천문학"],["丛书","cóngshū","총서"]]]},{"o":["明清时期的江南私家园林，大多出自文人画家之手，因而充满了诗情画意。","不少人误以为“多喝骨头汤能补钙”，其实骨头汤中的钙含量非常低。","当野兔察觉到天敌靠近时，它会先一动不动地伏在草丛中，等待最佳的逃跑时机。","由于近年来实施了严格的禁伐措施，大兴安岭林区的森林覆盖率仍在逐年下降。"],"a":3,"type":"인과 오용","why":"벌목 금지를 했으니 숲이 늘어야 한다. “由于”(원인)와 “仍在下降”(결과)이 논리적으로 맞지 않는다.","fix":"由于近年来实施了严格的禁伐措施，大兴安岭林区的森林覆盖率逐年上升。","words":[["禁伐","jìnfá","벌목 금지"],["大兴安岭","Dà Xīng'ān Lǐng","다싱안링"],["覆盖率","fùgàilǜ","피복률"],["私家园林","sījiā yuánlín","개인 정원"],["诗情画意","shī qíng huà yì","시와 그림 같은 정취"],["补钙","bǔgài","칼슘을 보충하다"],["察觉","chájué","알아차리다"],["天敌","tiāndí","천적"]],"tr":["명청 시대 강남의 개인 정원은 대부분 문인 화가의 손에서 나와, 시와 그림 같은 정취가 가득하다.","많은 사람이 '사골국을 많이 마시면 칼슘이 보충된다'고 잘못 알고 있지만, 사실 사골국의 칼슘 함량은 매우 낮다.","산토끼는 천적이 다가오는 것을 알아차리면 먼저 풀숲에 꼼짝 않고 엎드려 가장 좋은 도망칠 때를 기다린다.","최근 몇 년 동안 엄격한 벌목 금지 조치를 시행했기 때문에, 다싱안링 임구의 숲 면적 비율은 여전히 해마다 줄고 있다."],"ow":[[["私家园林","sījiā yuánlín","개인 정원"],["诗情画意","shī qíng huà yì","시와 그림 같은 정취"],["江南","Jiāngnán","강남(창장강 이남)"]],[["补钙","bǔgài","칼슘을 보충하다"],["骨头汤","gǔtoutāng","사골국"],["误以为","wù yǐwéi","잘못 알다"]],[["察觉","chájué","알아차리다"],["天敌","tiāndí","천적"],["靠","kào","의지하다"]],[["禁伐","jìnfá","벌목 금지"],["大兴安岭","Dà Xīng'ān Lǐng","다싱안링"],["覆盖率","fùgàilǜ","피복률"]]]},{"o":["新疆的魔鬼城是典型的雅丹地貌，经过长期风蚀，形成了千奇百怪的土丘。","这位青年学者关于古代丝织技术的研究成果得到了国际同行的高度评价，却先后被邀请到多所海外知名大学讲学。","人的记忆并非一成不变，每一次回忆都可能对原有的记忆进行重新加工。","为了让更多人接触古典音乐，这支交响乐团每年都会走进社区举办公益演出。"],"a":1,"type":"역접 오용","why":"좋은 평가를 받아서 초청을 받은 것이니 뜻이 이어진다. 반대를 나타내는 “却”를 쓰면 안 된다.","fix":"这位青年学者关于古代丝织技术的研究成果得到了国际同行的高度评价，并先后被邀请到多所海外知名大学讲学。","words":[["丝织","sīzhī","비단 짜기"],["魔鬼城","Móguǐ Chéng","마귀성"],["雅丹地貌","yǎdān dìmào","야르당 지형"],["风蚀","fēngshí","풍식"],["千奇百怪","qiān qí bǎi guài","기이한 모양이 가지각색이다"],["一成不变","yì chéng bú biàn","전혀 변하지 않다"],["交响乐团","jiāoxiǎng yuètuán","교향악단"]],"tr":["신장의 마귀성은 전형적인 야르당 지형으로, 오랜 바람의 침식을 받아 기기묘묘한 흙 언덕이 생겼다.","이 젊은 학자의 고대 비단 짜기 기술 연구는 국제 학계에서 높은 평가를 받았지만, 해외 명문 대학 여러 곳에 잇달아 강연 초청을 받았다.","사람의 기억은 고정된 것이 아니어서, 떠올릴 때마다 원래 기억이 새로 다듬어질 수 있다.","더 많은 사람이 클래식 음악을 접하도록, 이 교향악단은 해마다 지역 사회를 찾아가 공익 공연을 연다."],"ow":[[["魔鬼城","Móguǐ Chéng","마귀성"],["雅丹地貌","yǎdān dìmào","야르당 지형"],["风蚀","fēngshí","풍식"],["千奇百怪","qiān qí bǎi guài","기이한 모양이 가지각색이다"]],[["丝织","sīzhī","비단 짜기"],["讲学","jiǎngxué","강연하다"],["同行","tóngháng","같은 분야 사람"]],[["一成不变","yì chéng bú biàn","전혀 변하지 않다"],["并非","bìngfēi","결코 ~이 아니다"],["加工","jiāgōng","가공하다"]],[["交响乐团","jiāoxiǎng yuètuán","교향악단"],["公益","gōngyì","공익"],["接触","jiēchù","접하다"]]]},{"o":["山西大同的云冈石窟开凿于北魏时期，是中国现存规模最大的古代石窟群之一。","借助短视频平台，越来越多的年轻人开始自学烹饪、摄影等生活技能。","在四川发现的这种新的蕨类植物化石，不仅轰动了国际古生物学界，而且在国内引起了广泛关注。","每当暴风雨来临之前，海鸥总是成群地低飞，渔民们便知道该收网回港了。"],"a":2,"type":"점층 오용","why":"“不仅…而且…”는 작은 것에서 큰 것으로 가야 하는데, 국제에서 국내로 거꾸로 갔다.","fix":"在四川发现的这种新的蕨类植物化石，不仅在国内引起了广泛关注，而且轰动了国际古生物学界。","words":[["蕨类","juélèi","양치류"],["化石","huàshí","화석"],["轰动","hōngdòng","떠들썩하게 하다"],["古生物学","gǔshēngwùxué","고생물학"],["云冈石窟","Yúngāng Shíkū","윈강 석굴"],["北魏","Běi Wèi","북위"],["开凿","kāizáo","파서 만들다"],["海鸥","hǎi'ōu","갈매기"]],"tr":["산시성 다퉁의 윈강 석굴은 북위 시대에 만들어졌으며, 중국에 남아 있는 가장 큰 고대 석굴군 가운데 하나다.","숏폼 영상 플랫폼의 도움으로 요리, 사진 같은 생활 기술을 혼자 배우는 젊은이가 늘고 있다.","쓰촨에서 발견된 이 새로운 양치식물 화석은 국제 고생물학계를 떠들썩하게 했을 뿐 아니라, 국내에서도 큰 관심을 모았다.","폭풍우가 오기 전이면 갈매기들이 늘 떼 지어 낮게 날아, 어부들은 그물을 거두고 항구로 돌아갈 때임을 안다."],"ow":[[["云冈石窟","Yúngāng Shíkū","윈강 석굴"],["北魏","Běi Wèi","북위"],["开凿","kāizáo","파서 만들다"]],[["短视频","duǎnshìpín","숏폼 영상"],["烹饪","pēngrèn","요리"]],[["蕨类","juélèi","양치류"],["化石","huàshí","화석"],["轰动","hōngdòng","떠들썩하게 하다"],["古生物学","gǔshēngwùxué","고생물학"]],[["海鸥","hǎi'ōu","갈매기"],["暴风雨","bàofēngyǔ","폭풍우"],["收网","shōuwǎng","그물을 거두다"],["渔民","yúmín","어민"]]]},{"o":["在经历了多次失败之后，这家初创公司终于研发出了一款深受市场欢迎的产品。","对于如何平衡旅游开发与生态保护的问题上，专家们提出了不同的看法。","梵净山是武陵山脉的主峰，因保存着大面积原始森林而被列为世界自然遗产。","越是临近考试，越要保证充足的睡眠，否则复习效率会大打折扣。"],"a":1,"type":"개사 섞임","why":"“对于…”와 “在…问题上”이 섞였다. “在…的问题上”이나 “对于…的问题”로 써야 한다.","fix":"在如何平衡旅游开发与生态保护的问题上，专家们提出了不同的看法。","words":[["初创","chūchuàng","창업 초기의"],["研发","yánfā","연구 개발하다"],["梵净山","Fànjìng Shān","판징산"],["武陵山脉","Wǔlíng Shānmài","우링산맥"],["原始森林","yuánshǐ sēnlín","원시림"],["大打折扣","dà dǎ zhé kòu","크게 떨어지다"]],"tr":["여러 번 실패를 겪은 끝에, 이 스타트업은 마침내 시장에서 크게 환영받는 제품을 개발해 냈다.","관광 개발과 생태 보호의 균형을 어떻게 잡을지에 대해 전문가들은 서로 다른 의견을 내놓았다.","판징산은 우링산맥의 주봉으로, 넓은 원시림이 남아 있어 세계자연유산에 올랐다.","시험이 다가올수록 잠을 충분히 자야 한다. 그렇지 않으면 복습 효율이 크게 떨어진다."],"ow":[[["初创","chūchuàng","창업 초기의"],["研发","yánfā","연구 개발하다"]],[["旅游开发","lǚyóu kāifā","관광 개발"],["生态保护","shēngtài bǎohù","생태 보호"],["平衡","pínghéng","균형을 맞추다"]],[["梵净山","Fànjìng Shān","판징산"],["武陵山脉","Wǔlíng Shānmài","우링산맥"],["原始森林","yuánshǐ sēnlín","원시림"]],[["大打折扣","dà dǎ zhé kòu","크게 떨어지다"],["效率","xiàolǜ","효율"],["临近","línjìn","다가오다"]]]},{"o":["在当地牧民和野生动物救护人员的悉心照料，这只误入村庄、后腿受伤的野生小熊猫逐渐恢复了健康。","关于秦始皇陵地宫的种种传说，千百年来一直激发着人们的好奇心。","专家建议，老年人的饮食应以清淡为主，少吃过咸、过甜的食物。","这部历时五年拍摄完成的纪录片，用震撼的画面展现了中国从热带雨林到高原冰川的多样生态。"],"a":0,"type":"개사 빠짐","why":"“在…照料” 뒤에 “下”가 빠져 개사 구조가 끝나지 않았다.","fix":"在当地牧民和野生动物救护人员的悉心照料下，这只误入村庄、后腿受伤的野生小熊猫逐渐恢复了健康。","words":[["悉心","xīxīn","정성을 다하여"],["救护","jiùhù","구호하다"],["小熊猫","xiǎoxióngmāo","레서판다"],["秦始皇陵","Qínshǐhuáng Líng","진시황릉"],["地宫","dìgōng","지하 궁전"],["清淡","qīngdàn","담백하다"],["震撼","zhènhàn","뒤흔들다, 감동적이다"]],"tr":["현지 목축민과 야생동물 구조대원들의 정성 어린 보살핌 속에, 마을에 잘못 들어왔다가 뒷다리를 다친 야생 레서판다가 차츰 건강을 되찾았다.","진시황릉 지하 궁전에 얽힌 갖가지 전설은 천 년이 넘도록 사람들의 호기심을 자극해 왔다.","전문가들은 노인의 식사는 담백한 것을 위주로 하고, 너무 짜거나 단 음식은 적게 먹으라고 권한다.","5년에 걸쳐 촬영한 이 다큐멘터리는 강렬한 화면으로 열대 우림부터 고원 빙하까지 중국의 다양한 생태를 보여 준다."],"ow":[[["悉心","xīxīn","정성을 다하여"],["救护","jiùhù","구호하다"],["小熊猫","xiǎoxióngmāo","레서판다"],["牧民","mùmín","목축민"]],[["秦始皇陵","Qínshǐhuáng Líng","진시황릉"],["地宫","dìgōng","지하 궁전"]],[["清淡","qīngdàn","담백하다"],["饮食","yǐnshí","음식, 식사"]],[["震撼","zhènhàn","뒤흔들다, 감동적이다"],["热带雨林","rèdài yǔlín","열대 우림"],["纪录片","jìlùpiàn","다큐멘터리"],["冰川","bīngchuān","빙하"]]]}],[{"o":["南京云锦织造工艺复杂，一名熟练的织工一天往往只能织出五六厘米。","自动驾驶技术虽然发展迅速，但在复杂路况下的安全性仍有待验证。","四姑娘山景区明确规定，禁止游客不得在高山草甸上随意采摘野花、惊扰野生动物。","北极狐的毛色会随季节变化，冬季呈白色，夏季则变为灰褐色，以便与周围环境融为一体。"],"a":2,"type":"이중 부정","why":"“禁止”(못 하게 함)와 “不得”(하면 안 됨)가 겹쳐 뜻이 ‘하게 한다’로 뒤집힌다.","fix":"四姑娘山景区明确规定，禁止游客在高山草甸上随意采摘野花、惊扰野生动物。","words":[["四姑娘山","Sìgūniang Shān","쓰구냥산"],["草甸","cǎodiàn","초원 습지"],["采摘","cǎizhāi","따다"],["惊扰","jīngrǎo","놀라게 하다"],["云锦","yúnjǐn","운금(난징 비단)"],["有待","yǒudài","~할 필요가 있다"],["北极狐","běijíhú","북극여우"],["融为一体","róng wéi yì tǐ","하나로 녹아들다"]],"tr":["난징 운금은 짜는 공정이 복잡해, 숙련된 직공도 하루에 5~6센티미터밖에 짜지 못하는 경우가 많다.","자율 주행 기술은 빠르게 발전하고 있지만, 복잡한 도로 상황에서의 안전성은 아직 더 검증해야 한다.","쓰구냥산 관광지는 관광객이 고산 초원에서 함부로 들꽃을 꺾거나 야생동물을 놀라게 하는 것을 금지한다고 분명히 정했다.","북극여우의 털빛은 계절에 따라 바뀌어 겨울에는 흰색, 여름에는 회갈색이 되는데, 주변 환경에 녹아들기 위해서다."],"ow":[[["云锦","yúnjǐn","운금(난징 비단)"],["织工","zhīgōng","직공"],["织造","zhīzào","짜다"]],[["有待","yǒudài","~할 필요가 있다"],["自动驾驶","zìdòng jiàshǐ","자율 주행"],["路况","lùkuàng","도로 상황"],["验证","yànzhèng","검증하다"]],[["四姑娘山","Sìgūniang Shān","쓰구냥산"],["草甸","cǎodiàn","초원 습지"],["采摘","cǎizhāi","따다"],["惊扰","jīngrǎo","놀라게 하다"]],[["北极狐","běijíhú","북극여우"],["融为一体","róng wéi yì tǐ","하나로 녹아들다"]]]},{"o":["初学者在练习发音时难免会出现一些错误，关键是要敢于开口。","谁也无法否认，建立以国家公园为主体的自然保护地体系不是一项关系到生态安全和子孙后代福祉的重大决策。","徽派建筑以粉墙黛瓦、马头墙为主要特征，与周围的青山绿水相得益彰。","人们在做重大决定时，常常会不自觉地受到身边人意见的影响。"],"a":1,"type":"이중 부정","why":"“无法否认”에 “不是”까지 더해 ‘중대한 결정이 아니다’라는 뜻이 되어 버린다.","fix":"谁也无法否认，建立以国家公园为主体的自然保护地体系是一项关系到生态安全和子孙后代福祉的重大决策。","words":[["否认","fǒurèn","부인하다"],["福祉","fúzhǐ","복지, 행복"],["难免","nánmiǎn","피하기 어렵다"],["徽派","Huīpài","후이파(안후이 양식)"],["粉墙黛瓦","fěn qiáng dài wǎ","흰 벽과 검은 기와"],["相得益彰","xiāng dé yì zhāng","서로 돋보이게 하다"]],"tr":["처음 배우는 사람은 발음을 연습할 때 실수가 나오기 마련이니, 중요한 것은 과감하게 입을 여는 것이다.","국립공원을 중심으로 한 자연보호지 체계를 세우는 일이 생태 안전과 후손의 행복이 걸린 중대한 결정이라는 것은 누구도 부인할 수 없다.","후이파 건축은 흰 벽, 검은 기와, 마두장(층계 모양 방화벽)이 주된 특징으로, 주변의 푸른 산과 맑은 물과 서로를 돋보이게 한다.","사람은 중요한 결정을 내릴 때 자기도 모르게 주변 사람의 의견에 영향을 받곤 한다."],"ow":[[["难免","nánmiǎn","피하기 어렵다"],["敢于","gǎnyú","과감히 ~하다"]],[["否认","fǒurèn","부인하다"],["福祉","fúzhǐ","복지, 행복"],["重大","zhòngdà","중대하다"]],[["徽派","Huīpài","후이파(안후이 양식)"],["粉墙黛瓦","fěn qiáng dài wǎ","흰 벽과 검은 기와"],["相得益彰","xiāng dé yì zhāng","서로 돋보이게 하다"]],[["不自觉","bú zìjué","자기도 모르게"],["重大","zhòngdà","중대하다"]]]},{"o":["这个在旁人看来十分冒险的决定，对公司而言未必不是一次难得的转机。","吐鲁番盆地是中国陆地的最低点，夏季极端高温可达四十七摄氏度以上。","安徽泾县出产的宣纸质地绵韧、不易褪色，享有“纸寿千年”的美誉。","专家提醒，在野外遇到毒蛇时切忌不要惊慌乱跑，而应保持镇定、慢慢后退。"],"a":3,"type":"이중 부정","why":"“切忌”(절대 피하라)와 “不要”가 겹쳐 ‘당황해서 뛰지 않는 것을 피하라’는 뜻이 된다.","fix":"专家提醒，在野外遇到毒蛇时切忌惊慌乱跑，而应保持镇定、慢慢后退。","words":[["切忌","qièjì","절대 삼가다"],["镇定","zhèndìng","침착하다"],["未必","wèibì","꼭 ~한 것은 아니다"],["转机","zhuǎnjī","전환점"],["吐鲁番盆地","Tǔlǔfān Péndì","투루판 분지"],["宣纸","xuānzhǐ","선지(화선지)"],["绵韧","miánrèn","부드럽고 질기다"],["褪色","tuìsè","색이 바래다"]],"tr":["남들이 보기에 매우 모험적인 이 결정이, 회사로서는 오히려 흔치 않은 전환점이 될 수도 있다.","투루판 분지는 중국 육지에서 가장 낮은 곳으로, 여름 최고 기온이 섭씨 47도 이상까지 올라간다.","안후이성 징현에서 나는 선지는 부드럽고 질기며 잘 바래지 않아 '종이 수명 천 년'이라는 명성을 누린다.","전문가들은 야외에서 독사를 만나면 절대 당황해서 마구 달아나지 말고, 침착하게 천천히 뒤로 물러나라고 당부한다."],"ow":[[["未必","wèibì","꼭 ~한 것은 아니다"],["转机","zhuǎnjī","전환점"],["旁人","pángrén","남, 다른 사람"]],[["吐鲁番盆地","Tǔlǔfān Péndì","투루판 분지"],["摄氏度","shèshìdù","섭씨"],["极端","jíduān","극단적인"]],[["宣纸","xuānzhǐ","선지(화선지)"],["绵韧","miánrèn","부드럽고 질기다"],["褪色","tuìsè","색이 바래다"],["纸质","zhǐzhì","종이로 된"],["泾县","Jīng Xiàn","징현"]],[["切忌","qièjì","절대 삼가다"],["镇定","zhèndìng","침착하다"]]]},{"o":["得益于大规模植树造林，近二十年来科尔沁沙地每年的沙尘天数比过去减少了三倍。","与十年前相比，这座城市的公共图书馆数量增加了一倍。","东汉时期，蔡伦改进了造纸术，大大降低了书写材料的成本。","藏狐面部宽大方正，看上去总是一副无精打采的样子，因而在网络上走红。"],"a":0,"type":"배수 감소","why":"줄어드는 것은 “倍”로 말할 수 없다. “减少了一半”이나 “减少到原来的几分之一”처럼 분수로 쓴다.","fix":"得益于大规模植树造林，近二十年来科尔沁沙地每年的沙尘天数比过去减少了一半。","words":[["植树造林","zhí shù zào lín","나무를 심어 숲을 만들다"],["科尔沁沙地","Kē'ěrqìn Shādì","커얼친 사지"],["沙尘","shāchén","황사"],["蔡伦","Cài Lún","채륜"],["藏狐","zànghú","티베트모래여우"],["无精打采","wú jīng dǎ cǎi","풀이 죽다"],["走红","zǒuhóng","인기를 얻다"]],"tr":["대규모 나무 심기 덕분에 지난 20년 동안 커얼친 사지의 해마다 황사가 부는 날수가 예전보다 크게 줄었다.","10년 전에 비해 이 도시의 공공 도서관 수는 두 배로 늘었다.","동한 시대에 채륜은 종이 만드는 기술을 개량해 글을 쓰는 재료의 비용을 크게 낮췄다.","티베트모래여우는 얼굴이 넓고 네모나 늘 풀이 죽은 듯한 표정이어서 인터넷에서 인기를 끌었다."],"ow":[[["植树造林","zhí shù zào lín","나무를 심어 숲을 만들다"],["科尔沁沙地","Kē'ěrqìn Shādì","커얼친 사지"],["沙尘","shāchén","황사"]],[["公共图书馆","gōnggòng túshūguǎn","공공 도서관"],["一倍","yí bèi","배(두 배로 늚)"]],[["蔡伦","Cài Lún","채륜"],["造纸术","zàozhǐshù","제지술"]],[["藏狐","zànghú","티베트모래여우"],["无精打采","wú jīng dǎ cǎi","풀이 죽다"],["走红","zǒuhóng","인기를 얻다"]]]},{"o":["大鲵俗称“娃娃鱼”，因叫声酷似婴儿啼哭而得名，是现存最大的两栖动物。","北京四合院以院落为中心，四面建房，体现了中国传统的家族伦理观念。","采用新工艺后，这款手机芯片的功耗比上一代产品降低了一倍，续航时间则大幅延长。","据统计，今年前三季度该省的出口总额比去年同期增长了百分之十二。"],"a":2,"type":"배수 감소","why":"“降低”은 “倍”와 함께 쓸 수 없다. “降低了一半”이 맞다.","fix":"采用新工艺后，这款手机芯片的功耗比上一代产品降低了一半，续航时间则大幅延长。","words":[["芯片","xīnpiàn","칩"],["功耗","gōnghào","전력 소모"],["续航","xùháng","(배터리) 지속 시간"],["大鲵","dàní","중국장수도롱뇽"],["啼哭","tíkū","울다"],["两栖动物","liǎngqī dòngwù","양서류"],["四合院","sìhéyuàn","사합원"],["伦理","lúnlǐ","윤리"]],"tr":["중국장수도롱뇽은 흔히 '와와위(아기 물고기)'라고 불리는데, 울음소리가 아기 울음과 아주 비슷해서 붙은 이름이며, 지금 살아 있는 가장 큰 양서류다.","베이징 사합원은 마당을 가운데 두고 네 면에 집을 지은 것으로, 중국 전통의 가족 윤리관을 보여 준다.","새 공정을 쓴 뒤 이 휴대폰 칩의 전력 소모가 이전 세대보다 크게 줄고, 배터리 지속 시간은 크게 늘었다.","통계에 따르면 올해 1~3분기 이 성의 수출 총액은 지난해 같은 기간보다 12% 늘었다."],"ow":[[["大鲵","dàní","중국장수도롱뇽"],["啼哭","tíkū","울다"],["两栖动物","liǎngqī dòngwù","양서류"]],[["四合院","sìhéyuàn","사합원"],["伦理","lúnlǐ","윤리"]],[["芯片","xīnpiàn","칩"],["功耗","gōnghào","전력 소모"],["续航","xùháng","(배터리) 지속 시간"],["一倍","yí bèi","배(두 배로 늚)"]],[["季度","jìdù","분기"],["同期","tóngqī","같은 시기"]]]},{"o":["习惯性拖延的人并非都是因为懒惰，有些人恰恰是因为过于追求完美而迟迟不肯动手。","皮影戏是一种用灯光把兽皮雕刻的人物剪影投射到幕布上进行表演的民间戏剧。","近年来，新能源汽车的销量持续攀升，在乘用车市场中所占的比重越来越大。","小兴安岭的原始森林里，生长着红松、云杉、冷杉和针叶树等多种高大乔木。"],"a":3,"type":"범위·분류","why":"“红松·云杉·冷杉”은 모두 “针叶树”에 속한다. 큰 범주와 작은 범주를 나란히 늘어놓았다.","fix":"小兴安岭的原始森林里，生长着红松、云杉、冷杉等多种高大的针叶乔木。","words":[["小兴安岭","Xiǎo Xīng'ān Lǐng","샤오싱안링"],["云杉","yúnshān","가문비나무"],["冷杉","lěngshān","전나무"],["针叶","zhēnyè","바늘잎"],["乔木","qiáomù","교목"],["拖延","tuōyán","미루다"],["皮影戏","píyǐngxì","그림자극"],["攀升","pānshēng","오르다"]],"tr":["습관적으로 일을 미루는 사람이 모두 게을러서 그런 것은 아니다. 어떤 사람은 오히려 완벽을 너무 추구해서 좀처럼 손을 대지 못한다.","그림자극은 짐승 가죽을 새겨 만든 인물 실루엣을 불빛으로 막에 비추어 공연하는 민간 연극이다.","최근 몇 년 동안 신에너지 자동차 판매량이 꾸준히 늘어, 승용차 시장에서 차지하는 비중이 점점 커지고 있다.","샤오싱안링의 원시림에는 잣나무, 가문비나무, 전나무 등 키 큰 침엽수가 여러 종 자란다."],"ow":[[["拖延","tuōyán","미루다"],["追求完美","zhuīqiú wánměi","완벽을 추구하다"],["懒惰","lǎnduò","게으르다"],["恰恰","qiàqià","바로, 오히려"],["并非","bìngfēi","결코 ~이 아니다"]],[["皮影戏","píyǐngxì","그림자극"],["剪影","jiǎnyǐng","실루엣"],["投射","tóushè","비추다"],["幕布","mùbù","막"]],[["攀升","pānshēng","오르다"],["乘用车","chéngyòngchē","승용차"],["销量","xiāoliàng","판매량"],["比重","bǐzhòng","비중"]],[["小兴安岭","Xiǎo Xīng'ān Lǐng","샤오싱안링"],["云杉","yúnshān","가문비나무"],["冷杉","lěngshān","전나무"],["针叶","zhēnyè","바늘잎"],["乔木","qiáomù","교목"]]]},{"o":["每年端午节前后，前来湖南汨罗江畔观看龙舟赛的中外游客和外国友人多达数万人。","长江正源沱沱河发源于唐古拉山脉主峰各拉丹冬雪山西南侧的冰川。","在古代，铜镜不仅是日常生活用品，还常被当作馈赠亲友的珍贵礼物。","这项技术不仅可以用于医疗诊断，还有望在农业育种领域得到应用。"],"a":0,"type":"범위·분류","why":"“中外游客”에 이미 외국인이 들어 있어 “外国友人”과 범위가 겹친다.","fix":"每年端午节前后，前来湖南汨罗江畔观看龙舟赛的中外游客多达数万人。","words":[["汨罗江","Mìluó Jiāng","미뤄강"],["龙舟","lóngzhōu","용선"],["沱沱河","Tuótuó Hé","퉈퉈허"],["唐古拉山脉","Tánggǔlā Shānmài","탕구라산맥"],["各拉丹冬","Gèlādāndōng","거라단둥(설산)"],["馈赠","kuìzèng","선사하다"],["育种","yùzhǒng","육종"]],"tr":["해마다 단오 무렵이면 후난성 미뤄강 가로 용선 경주를 보러 오는 국내외 관광객이 수만 명에 이른다.","창장강의 본류 발원지인 퉈퉈허는 탕구라산맥 주봉 거라단둥 설산의 서남쪽 빙하에서 시작된다.","옛날에 청동 거울은 생활용품이었을 뿐 아니라, 가족과 친구에게 주는 귀한 선물로도 자주 쓰였다.","이 기술은 의료 진단에 쓰일 수 있을 뿐 아니라, 농업 품종 개량 분야에서도 쓰일 가능성이 있다."],"ow":[[["汨罗江","Mìluó Jiāng","미뤄강"],["龙舟","lóngzhōu","용선"]],[["沱沱河","Tuótuó Hé","퉈퉈허"],["唐古拉山脉","Tánggǔlā Shānmài","탕구라산맥"],["各拉丹冬","Gèlādāndōng","거라단둥(설산)"],["冰川","bīngchuān","빙하"]],[["馈赠","kuìzèng","선사하다"],["铜镜","tóngjìng","청동 거울"]],[["育种","yùzhǒng","육종"],["诊断","zhěnduàn","진단"],["有望","yǒuwàng","가능성이 있다"]]]},{"o":["冬季的拉萨河谷，常能见到成群的赤麻鸭在河滩和青稞地里觅食。","考古学家根据出土的陶器和炭化稻谷推断，这处遗址肯定大约形成于七千年前的新石器时代。","这本小说一经出版便受到热捧，短短一个月内就加印了五次。","中国古代的天文学家很早就对哈雷彗星进行了记录，其中《春秋》中的记载被认为是世界上最早的。"],"a":1,"type":"자기모순","why":"“肯定”(확실함)와 “大约”(어림)가 함께 있어 앞뒤가 맞지 않는다.","fix":"考古学家根据出土的陶器和炭化稻谷推断，这处遗址大约形成于七千年前的新石器时代。","words":[["陶器","táoqì","도기"],["炭化","tànhuà","탄화"],["新石器时代","xīnshíqì shídài","신석기 시대"],["赤麻鸭","chìmáyā","황오리"],["青稞","qīngkē","쌀보리"],["觅食","mìshí","먹이를 찾다"],["热捧","rèpěng","열렬히 지지하다"],["哈雷彗星","Hāléi huìxīng","핼리 혜성"]],"tr":["겨울 라싸 강 골짜기에서는 황오리 떼가 강변과 쌀보리 밭에서 먹이를 찾는 모습을 흔히 볼 수 있다.","고고학자들은 출토된 도기와 탄화된 볍씨를 근거로, 이 유적이 틀림없이 약 7천 년 전 신석기 시대에 생겼다고 추정했다.","이 소설은 나오자마자 큰 인기를 끌어, 한 달 만에 다섯 번이나 다시 찍었다.","중국 고대 천문학자들은 일찍부터 핼리 혜성을 기록했으며, 그중 「춘추」의 기록은 세계에서 가장 오래된 것으로 여겨진다."],"ow":[[["赤麻鸭","chìmáyā","황오리"],["青稞","qīngkē","쌀보리"],["觅食","mìshí","먹이를 찾다"]],[["陶器","táoqì","도기"],["炭化","tànhuà","탄화"],["新石器时代","xīnshíqì shídài","신석기 시대"]],[["热捧","rèpěng","열렬히 지지하다"],["加印","jiāyìn","더 찍다"],["一经","yìjīng","일단 ~하자"]],[["哈雷彗星","Hāléi huìxīng","핼리 혜성"],["天文学","tiānwénxué","천문학"],["记载","jìzǎi","기록"],["春秋","Chūnqiū","춘추(시대·사서)"]]]},{"o":["这位刺绣大师的作品针法细密、色彩雅致，几可乱真，令人叹为观止。","在这次全国性的调查中，八成以上的受访者表示愿意为环保产品支付更高的价格。","古人常以松、竹、梅比喻高洁的品格，并称之为“岁寒三友”。","这次考察共发现了二十三种珍稀植物，其中十五种为国家一级保护植物，另有十种为二级保护植物。"],"a":3,"type":"자기모순","why":"15종과 10종을 더하면 25종인데 전체가 23종이라 숫자가 앞뒤로 맞지 않는다.","fix":"这次考察共发现了二十三种珍稀植物，其中十五种为国家一级保护植物，另有八种为二级保护植物。","words":[["针法","zhēnfǎ","바느질 기법"],["雅致","yǎzhì","우아하다"],["几可乱真","jī kě luàn zhēn","진짜와 거의 구별되지 않다"],["叹为观止","tàn wéi guān zhǐ","감탄해 마지않다"],["受访者","shòufǎngzhě","응답자"],["高洁","gāojié","고결하다"],["岁寒三友","suì hán sān yǒu","세한삼우(송·죽·매)"]],"tr":["이 자수 장인의 작품은 바느질이 촘촘하고 색이 우아해 진짜와 거의 구별이 안 될 정도라, 보는 이를 감탄하게 한다.","이번 전국 조사에서 응답자의 80% 이상이 친환경 제품에 더 높은 값을 낼 의향이 있다고 답했다.","옛사람들은 소나무, 대나무, 매화로 고결한 품성을 비유하며 이를 '세한삼우'라고 불렀다.","이번 탐사에서 희귀 식물을 모두 23종 발견했는데, 그중 15종은 국가 1급 보호 식물이고 나머지 10종은 2급 보호 식물이다."],"ow":[[["针法","zhēnfǎ","바느질 기법"],["雅致","yǎzhì","우아하다"],["几可乱真","jī kě luàn zhēn","진짜와 거의 구별되지 않다"],["叹为观止","tàn wéi guān zhǐ","감탄해 마지않다"]],[["受访者","shòufǎngzhě","응답자"],["环保","huánbǎo","환경 보호"],["支付","zhīfù","지불하다"]],[["高洁","gāojié","고결하다"],["岁寒三友","suì hán sān yǒu","세한삼우(송·죽·매)"]],[["保护植物","bǎohù zhíwù","보호 식물"],["珍稀","zhēnxī","진귀하고 드물다"],["考察","kǎochá","탐사하다"]]]},{"o":["苏州评弹用吴侬软语演唱，曲调婉转悠扬，被誉为“中国最美的声音”。","摆手舞是土家族最具代表性的传统舞蹈，舞者同边的手脚一齐摆动，动作古朴而粗犷。","据初步估算，这次山体滑坡造成的直接经济损失至少在三千万元左右，所幸没有人员伤亡。","红树林被称为“海岸卫士”，能够有效减轻风暴潮对海岸的冲击。"],"a":2,"type":"자기모순","why":"“至少”(최소한)와 “左右”(대략 그쯤)가 함께 있어 뜻이 부딪친다.","fix":"据初步估算，这次山体滑坡造成的直接经济损失至少达三千万元，所幸没有人员伤亡。","words":[["山体滑坡","shāntǐ huápō","산사태"],["所幸","suǒxìng","다행히"],["评弹","píngtán","평탄(쑤저우 설창)"],["吴侬软语","Wú nóng ruǎn yǔ","부드러운 오 지방 말씨"],["婉转悠扬","wǎnzhuǎn yōuyáng","곱고 은은하다"],["红树林","hóngshùlín","맹그로브 숲"],["摆手舞","bǎishǒuwǔ","바이서우춤"],["土家族","Tǔjiāzú","투자족"]],"tr":["쑤저우 평탄은 부드러운 오 지방 말씨로 노래하며 가락이 곱고 은은해 '중국에서 가장 아름다운 소리'로 불린다.","바이서우춤은 투자족을 가장 잘 대표하는 전통 춤으로, 춤추는 사람이 같은 쪽 손발을 함께 흔들어 동작이 예스럽고 호방하다.","초기 추산으로 이번 산사태의 직접 경제 손실은 최소 3천만 위안 정도인데, 다행히 인명 피해는 없었다.","맹그로브 숲은 '해안 지킴이'로 불리며, 폭풍 해일이 해안에 주는 충격을 효과적으로 줄일 수 있다."],"ow":[[["评弹","píngtán","평탄(쑤저우 설창)"],["吴侬软语","Wú nóng ruǎn yǔ","부드러운 오 지방 말씨"],["婉转悠扬","wǎnzhuǎn yōuyáng","곱고 은은하다"]],[["摆手舞","bǎishǒuwǔ","바이서우춤"],["土家族","Tǔjiāzú","투자족"]],[["山体滑坡","shāntǐ huápō","산사태"],["所幸","suǒxìng","다행히"]],[["红树林","hóngshùlín","맹그로브 숲"],["风暴潮","fēngbàocháo","폭풍 해일"],["卫士","wèishì","지킴이"]]]}],[{"o":["提起江南，人们脑海中浮现的往往是小桥流水、烟雨朦胧的诗意画面。","专家分析，近年来洞庭湖枯水期提前的主要原因，是上游来水减少和河道下切共同造成的。","这位年轻导演历时三年拍摄的处女作，在上映前就被不少影评人所看好。","北宋时期，四川地区出现了世界上最早的纸币“交子”。"],"a":1,"type":"구식 혼합","why":"“原因是…”와 “…是…造成的” 두 문형이 섞였다.","fix":"专家分析，近年来洞庭湖枯水期提前，主要是上游来水减少和河道下切共同造成的。","words":[["洞庭湖","Dòngtíng Hú","둥팅호"],["枯水期","kūshuǐqī","갈수기"],["下切","xiàqiē","(강바닥이) 깊이 깎이다"],["朦胧","ménglóng","몽롱하다, 흐릿하다"],["处女作","chǔnǚzuò","데뷔작"],["影评人","yǐngpíngrén","영화 평론가"],["交子","jiāozǐ","교자(지폐)"]],"tr":["강남이라고 하면 사람들은 흔히 작은 다리와 흐르는 물, 안개비에 흐릿한 시적인 풍경을 떠올린다.","전문가들은 최근 둥팅호의 갈수기가 앞당겨진 주된 원인이 상류에서 들어오는 물이 줄고 강바닥이 깊이 깎인 데 있다고 분석했다.","이 젊은 감독이 3년에 걸쳐 찍은 데뷔작은 개봉 전부터 많은 영화 평론가의 기대를 받았다.","북송 시대에 쓰촨 지역에서 세계 최초의 지폐 '교자'가 나타났다."],"ow":[[["朦胧","ménglóng","몽롱하다, 흐릿하다"],["小桥流水","xiǎo qiáo liú shuǐ","작은 다리와 흐르는 물"],["江南","Jiāngnán","강남(창장강 이남)"],["烟雨","yānyǔ","안개비"]],[["洞庭湖","Dòngtíng Hú","둥팅호"],["枯水期","kūshuǐqī","갈수기"],["下切","xiàqiē","(강바닥이) 깊이 깎이다"]],[["处女作","chǔnǚzuò","데뷔작"],["影评人","yǐngpíngrén","영화 평론가"],["上映","shàngyìng","개봉하다"]],[["交子","jiāozǐ","교자(지폐)"],["纸币","zhǐbì","지폐"]]]},{"o":["在漫长的冬季，生活在羌塘高原上的藏野驴主要靠枯黄的牧草和灌木的嫩枝为食。","比起一味地批评指责，耐心地倾听往往更能拉近与孩子之间的距离。","每到金秋时节，苏州阳澄湖出产的大闸蟹膏满黄肥，吸引着各地食客慕名而来。","重阳节之所以又被称为“老人节”，是因为“九九”与“久久”谐音，寓意健康长寿。"],"a":0,"type":"구식 혼합","why":"“靠…生存”과 “以…为食” 두 문형이 섞였다.","fix":"在漫长的冬季，生活在羌塘高原上的藏野驴主要以枯黄的牧草和灌木的嫩枝为食。","words":[["羌塘","Qiāngtáng","창탕"],["藏野驴","zàngyělǘ","티베트야생당나귀"],["灌木","guànmù","관목"],["嫩枝","nènzhī","어린 가지"],["倾听","qīngtīng","귀 기울여 듣다"],["谐音","xiéyīn","발음이 같다"],["阳澄湖","Yángchéng Hú","양청호"],["大闸蟹","dàzháxiè","털게"]],"tr":["긴 겨울 동안 창탕 고원에 사는 티베트야생당나귀는 주로 누렇게 마른 풀과 관목의 어린 가지를 먹고 산다.","무턱대고 꾸짖고 나무라기보다 참을성 있게 들어 주는 것이 아이와의 거리를 더 좁힐 수 있다.","해마다 가을이면 쑤저우 양청호에서 나는 털게가 알과 장이 꽉 차, 곳곳의 미식가들이 소문을 듣고 찾아온다.","중양절을 '노인의 날'이라고도 부르는 것은 '九九(주주)'가 '久久(오래오래)'와 발음이 같아 건강하게 오래 산다는 뜻을 담기 때문이다."],"ow":[[["羌塘","Qiāngtáng","창탕"],["藏野驴","zàngyělǘ","티베트야생당나귀"],["灌木","guànmù","관목"],["嫩枝","nènzhī","어린 가지"],["靠","kào","의지하다"]],[["倾听","qīngtīng","귀 기울여 듣다"],["一味","yíwèi","무턱대고"],["指责","zhǐzé","나무라다"]],[["阳澄湖","Yángchéng Hú","양청호"],["大闸蟹","dàzháxiè","털게"]],[["谐音","xiéyīn","발음이 같다"],["重阳节","Chóngyáng Jié","중양절"],["寓意","yùyì","뜻을 담다"]]]},{"o":["北京的中轴线南起永定门，北至钟鼓楼，全长约七点八公里。","为了减少塑料污染，不少超市已经停止免费提供一次性塑料袋。","梅雨是我国长江中下游地区每年初夏特有的天气现象，因正值江南梅子成熟而得名。","一个物种能否在新的环境中存活下来，关键在于它对当地气候和食物资源的适应能力起着决定性作用。"],"a":3,"type":"구식 혼합","why":"“关键在于…”와 “…起着决定性作用” 두 문형이 섞였다.","fix":"一个物种能否在新的环境中存活下来，关键在于它对当地气候和食物资源的适应能力。","words":[["存活","cúnhuó","살아남다"],["中轴线","zhōngzhóuxiàn","중축선"],["永定门","Yǒngdìng Mén","융딩먼"],["钟鼓楼","Zhōnggǔ Lóu","종고루"],["一次性","yícìxìng","일회용"],["梅雨","méiyǔ","장마"],["正值","zhèngzhí","마침 ~때이다"]],"tr":["베이징의 중축선은 남쪽 융딩먼에서 북쪽 종고루까지로, 전체 길이가 약 7.8킬로미터다.","플라스틱 오염을 줄이려고 많은 슈퍼마켓이 이미 일회용 비닐봉지를 무료로 주지 않는다.","장마는 우리나라 창장강 중하류 지역에서 해마다 초여름에 나타나는 특유의 날씨로, 강남의 매실이 익을 때라서 붙은 이름이다.","한 생물 종이 새로운 환경에서 살아남을 수 있을지는 그 지역의 기후와 먹이에 적응하는 능력에 달려 있다."],"ow":[[["中轴线","zhōngzhóuxiàn","중축선"],["永定门","Yǒngdìng Mén","융딩먼"],["钟鼓楼","Zhōnggǔ Lóu","종고루"]],[["一次性","yícìxìng","일회용"],["塑料","sùliào","플라스틱"]],[["梅雨","méiyǔ","장마"],["正值","zhèngzhí","마침 ~때이다"],["中下游","zhōngxiàyóu","중하류"],["江南","Jiāngnán","강남(창장강 이남)"]],[["存活","cúnhuó","살아남다"],["物种","wùzhǒng","생물 종"]]]},{"o":["医生指出，这名患者的长期失眠主要是工作压力过大所致。","清代画家郑板桥以画竹著称，他笔下的竹子清瘦挺拔，富有傲骨。","这次大规模的联合科考，是为了全面摸清南海海草床的分布与退化状况为目的而组织的。","在数字经济时代，数据已经成为与土地、劳动力、资本同等重要的生产要素。"],"a":2,"type":"구식 혼합","why":"“是为了…而组织的”와 “以…为目的” 두 문형이 섞였다.","fix":"这次大规模的联合科考，是为了全面摸清南海海草床的分布与退化状况而组织的。","words":[["海草床","hǎicǎochuáng","해초밭"],["摸清","mōqīng","정확히 파악하다"],["所致","suǒzhì","~로 인한 것이다"],["郑板桥","Zhèng Bǎnqiáo","정판교"],["挺拔","tǐngbá","곧게 솟다"],["傲骨","àogǔ","굽히지 않는 기개"],["生产要素","shēngchǎn yàosù","생산 요소"]],"tr":["의사는 이 환자의 오랜 불면증이 주로 지나친 업무 스트레스 때문이라고 짚었다.","청나라 화가 정판교는 대나무 그림으로 유명하며, 그가 그린 대나무는 가늘고 곧게 솟아 굽히지 않는 기개가 넘친다.","이번 대규모 공동 탐사는 남중국해 해초밭의 분포와 훼손 상황을 정확히 파악하기 위해 꾸려졌다.","디지털 경제 시대에 데이터는 이미 토지, 노동력, 자본만큼 중요한 생산 요소가 되었다."],"ow":[[["所致","suǒzhì","~로 인한 것이다"],["失眠","shīmián","불면"],["患者","huànzhě","환자"]],[["郑板桥","Zhèng Bǎnqiáo","정판교"],["挺拔","tǐngbá","곧게 솟다"],["傲骨","àogǔ","굽히지 않는 기개"]],[["海草床","hǎicǎochuáng","해초밭"],["摸清","mōqīng","정확히 파악하다"]],[["生产要素","shēngchǎn yàosù","생산 요소"],["数字经济","shùzì jīngjì","디지털 경제"],["资本","zīběn","자본"]]]},{"o":["汉语中的许多成语源于古代寓言，如“守株待兔”“刻舟求剑”等，至今仍被广泛使用。","越是物质丰富的年代，人们越需要警惕消费主义带来的精神空虚。","鄂温克族的一支世代生活在内蒙古东北部的密林深处，以饲养驯鹿而闻名。","经过科研人员长达八年的人工授粉和野外回归试验，使一度被认为已在野外灭绝的百山祖冷杉重新在浙江南部的山林中扎下了根。"],"a":3,"type":"주어 결여","why":"“经过…，使…” 때문에 “扎下了根”의 주어가 없다. 使를 빼야 한다.","fix":"经过科研人员长达八年的人工授粉和野外回归试验，一度被认为已在野外灭绝的百山祖冷杉重新在浙江南部的山林中扎下了根。","words":[["授粉","shòufěn","수분하다"],["百山祖冷杉","Bǎishānzǔ lěngshān","바이산쭈전나무"],["寓言","yùyán","우화"],["守株待兔","shǒu zhū dài tù","그루터기를 지켜 토끼를 기다리다"],["刻舟求剑","kè zhōu qiú jiàn","배에 표시해 칼을 찾다"],["警惕","jǐngtì","경계하다"],["鄂温克族","Èwēnkèzú","어원커족"],["驯鹿","xùnlù","순록"]],"tr":["중국어의 많은 성어는 옛 우화에서 나왔는데, '그루터기를 지켜 토끼를 기다린다'나 '배에 표시해 칼을 찾는다' 같은 것은 지금도 널리 쓰인다.","물질이 풍족한 시대일수록 사람들은 소비주의가 가져오는 정신적 공허를 더 경계해야 한다.","어원커족의 한 갈래는 대대로 내몽골 동북부의 깊은 숲속에서 살며 순록을 기르는 것으로 이름나 있다.","연구자들이 8년 동안 인공 수분과 야생 복원 실험을 한 끝에, 한때 야생에서 멸종한 것으로 여겨졌던 바이산쭈전나무가 저장성 남부 산림에 다시 뿌리를 내렸다."],"ow":[[["寓言","yùyán","우화"],["守株待兔","shǒu zhū dài tù","그루터기를 지켜 토끼를 기다리다"],["刻舟求剑","kè zhōu qiú jiàn","배에 표시해 칼을 찾다"]],[["警惕","jǐngtì","경계하다"],["消费主义","xiāofèi zhǔyì","소비주의"],["空虚","kōngxū","공허하다"]],[["鄂温克族","Èwēnkèzú","어원커족"],["驯鹿","xùnlù","순록"]],[["授粉","shòufěn","수분하다"],["百山祖冷杉","Bǎishānzǔ lěngshān","바이산쭈전나무"],["江南","Jiāngnán","강남(창장강 이남)"]]]},{"o":["近年来，青海三江源地区通过设立生态管护员公益岗位，既守护了雪山、草原和湿地，又显著提高了当地牧民的生活面貌。","与其说他是一位商人，不如说他是一位怀有文化情怀的收藏家。","敦煌壁画中的飞天形象衣带飘舞，体态轻盈，展现了古代画师非凡的想象力。","人在极度疲劳时做出的判断，往往远不如精力充沛时可靠。"],"a":0,"type":"동사–목적어","why":"“提高”는 “面貌”와 어울리지 않는다. “改善…面貌”나 “提高…水平”이 맞다.","fix":"近年来，青海三江源地区通过设立生态管护员公益岗位，既守护了雪山、草原和湿地，又显著改善了当地牧民的生活面貌。","words":[["管护员","guǎnhùyuán","관리 보호원"],["守护","shǒuhù","지키다"],["面貌","miànmào","모습, 양상"],["情怀","qínghuái","정서, 마음"],["飞天","fēitiān","비천(하늘을 나는 선녀)"],["轻盈","qīngyíng","가뿐하다"],["充沛","chōngpèi","넘쳐흐르다"]],"tr":["최근 칭하이 싼장위안 지역은 생태 관리 보호원 공익 일자리를 만들어, 설산과 초원과 습지를 지키는 동시에 현지 목축민의 생활 모습도 크게 바꾸었다.","그는 상인이라기보다 문화에 대한 애정을 품은 수집가라고 하는 편이 맞다.","둔황 벽화 속 비천은 옷자락이 나부끼고 몸놀림이 가벼워, 옛 화공들의 놀라운 상상력을 보여 준다.","몹시 지쳤을 때 내린 판단은 기운이 넘칠 때보다 훨씬 덜 믿을 만한 경우가 많다."],"ow":[[["管护员","guǎnhùyuán","관리 보호원"],["守护","shǒuhù","지키다"],["面貌","miànmào","모습, 양상"],["公益","gōngyì","공익"],["牧民","mùmín","목축민"]],[["情怀","qínghuái","정서, 마음"],["收藏家","shōucángjiā","수집가"]],[["飞天","fēitiān","비천(하늘을 나는 선녀)"],["轻盈","qīngyíng","가뿐하다"]],[["充沛","chōngpèi","넘쳐흐르다"],["可靠","kěkào","믿을 만하다"],["疲劳","píláo","피로하다"],["精力","jīnglì","기력"]]]},{"o":["中国画讲究“留白”，画面上看似空无一物之处，往往给人留下无限的想象空间。","随着冷链物流的完善，产自云南的鲜花当天就能运抵全国各大城市。","初到高原的游客如果不注意休息，就难免不会出现头晕、胸闷等不适症状。","这位修复师在敦煌壁画修复领域取得的成就，离不开他几十年如一日的潜心钻研。"],"a":2,"type":"이중 부정","why":"“难免”(피하기 어렵다) 뒤에 “不会”가 붙어 ‘나타나지 않는 것을 피하기 어렵다’로 뜻이 뒤집힌다.","fix":"初到高原的游客如果不注意休息，就难免会出现头晕、胸闷等不适症状。","words":[["胸闷","xiōngmèn","가슴이 답답하다"],["留白","liúbái","여백을 남기다"],["冷链","lěngliàn","콜드체인"],["运抵","yùndǐ","운송되어 도착하다"],["几十年如一日","jǐ shí nián rú yí rì","수십 년을 하루같이"],["潜心","qiánxīn","몰두하다"],["钻研","zuānyán","깊이 연구하다"]],"tr":["중국화는 '여백'을 중시해서, 화면에서 아무것도 없어 보이는 곳이 오히려 끝없는 상상의 공간을 남겨 준다.","콜드체인 물류가 갖춰지면서 윈난에서 난 꽃이 그날 바로 전국 대도시에 도착할 수 있게 되었다.","고원에 처음 온 관광객은 쉬는 데 신경 쓰지 않으면 어지럼증과 가슴 답답함 같은 증상이 나타나기 쉽다.","이 복원가가 둔황 벽화 복원 분야에서 이룬 성과는 수십 년을 하루같이 연구에 몰두한 덕분이다."],"ow":[[["留白","liúbái","여백을 남기다"],["空无一物","kōng wú yí wù","아무것도 없다"]],[["冷链","lěngliàn","콜드체인"],["运抵","yùndǐ","운송되어 도착하다"]],[["胸闷","xiōngmèn","가슴이 답답하다"],["头晕","tóuyūn","어지럽다"],["症状","zhèngzhuàng","증상"]],[["几十年如一日","jǐ shí nián rú yí rì","수십 년을 하루같이"],["潜心","qiánxīn","몰두하다"],["钻研","zuānyán","깊이 연구하다"],["修复","xiūfù","복원하다"]]]},{"o":["即便是在信息高度发达的今天，面对面的交流依然具有无法替代的价值。","灰鹤是一种典型的候鸟，它们每年不是在内蒙古东部的湿地繁殖，而是到长江中下游地区越冬。","清明前后采摘的西湖龙井，色泽翠绿，香气清高，被视为龙井茶中的上品。","这项改革之所以阻力重重，是因为它触动了部分群体的既得利益。"],"a":1,"type":"관련사 논리","why":"“不是…而是…”는 앞을 부정하는데, 회색두루미는 번식도 하고 월동도 한다. 두 가지를 다 하는 관계라 맞지 않는다.","fix":"灰鹤是一种典型的候鸟，它们每年夏季在内蒙古东部的湿地繁殖，冬季则到长江中下游地区越冬。","words":[["灰鹤","huīhè","재두루미(회색두루미)"],["候鸟","hòuniǎo","철새"],["繁殖","fánzhí","번식하다"],["替代","tìdài","대체하다"],["龙井","Lóngjǐng","룽징차"],["色泽","sèzé","빛깔과 광택"],["阻力","zǔlì","저항"],["既得利益","jìdé lìyì","기득권"]],"tr":["정보가 고도로 발달한 오늘날에도 얼굴을 마주하고 나누는 대화는 여전히 무엇으로도 대신할 수 없는 가치가 있다.","재두루미는 대표적인 철새로, 해마다 내몽골 동부 습지에서 번식하고 창장강 중하류 지역으로 가서 겨울을 난다.","청명 무렵에 딴 시후 룽징차는 빛깔이 비취처럼 푸르고 향이 맑고 그윽해, 룽징차 가운데 최상품으로 여겨진다.","이 개혁이 큰 저항에 부딪힌 것은 일부 집단의 기득권을 건드렸기 때문이다."],"ow":[[["替代","tìdài","대체하다"],["即便","jíbiàn","설령 ~라도"]],[["灰鹤","huīhè","재두루미(회색두루미)"],["候鸟","hòuniǎo","철새"],["繁殖","fánzhí","번식하다"],["中下游","zhōngxiàyóu","중하류"]],[["龙井","Lóngjǐng","룽징차"],["色泽","sèzé","빛깔과 광택"]],[["阻力","zǔlì","저항"],["既得利益","jìdé lìyì","기득권"]]]},{"o":["一个国家的科技创新能力强弱，在很大程度上取决于它对基础研究的长期投入。","明代的嘉峪关被称为“天下第一雄关”，是万里长城西端的重要关隘。","据考证，山东莒县浮来山上的这棵银杏树龄已逾三千年以上，被誉为“天下银杏第一树”。","长期伏案工作的人，应当每隔一小时起身活动片刻，以缓解颈椎的压力。"],"a":2,"type":"어림수 중복","why":"“逾”가 이미 ‘넘다’라는 뜻이라 “以上”과 겹친다.","fix":"据考证，山东莒县浮来山上的这棵银杏树龄已逾三千年，被誉为“天下银杏第一树”。","words":[["考证","kǎozhèng","고증하다"],["莒县","Jǔ Xiàn","쥐현"],["银杏","yínxìng","은행나무"],["逾","yú","넘다"],["嘉峪关","Jiāyù Guān","자위관"],["关隘","guān'ài","요새 관문"],["伏案","fú'àn","책상에 엎드리다"],["颈椎","jǐngzhuī","목뼈"]],"tr":["한 나라의 과학 기술 혁신 능력이 강한지 약한지는 기초 연구에 오랫동안 얼마나 투자하느냐에 크게 달려 있다.","명나라의 자위관은 '천하제일 웅관'으로 불리며, 만리장성 서쪽 끝의 중요한 관문이다.","고증에 따르면 산둥성 쥐현 푸라이산의 이 은행나무는 나이가 3천 년이 넘어 '천하제일 은행나무'로 불린다.","오래 책상에 앉아 일하는 사람은 한 시간마다 일어나 잠깐 몸을 움직여 목뼈의 부담을 덜어야 한다."],"ow":[[["基础研究","jīchǔ yánjiū","기초 연구"],["取决于","qǔjué yú","~에 달려 있다"],["程度","chéngdù","정도"]],[["嘉峪关","Jiāyù Guān","자위관"],["关隘","guān'ài","요새 관문"]],[["考证","kǎozhèng","고증하다"],["莒县","Jǔ Xiàn","쥐현"],["银杏","yínxìng","은행나무"],["逾","yú","넘다"]],[["伏案","fú'àn","책상에 엎드리다"],["颈椎","jǐngzhuī","목뼈"]]]},{"o":["一座城市的公共交通是否便捷，往往是年轻人选择在哪里定居时考虑的重要因素。","中国的藏书文化源远流长，宁波的天一阁是现存最古老的私家藏书楼。","在线教育打破了时间和空间的限制，让偏远地区的学生也能享受到优质的教学资源。","为了避免那些树龄超过千年的古柏不再遭受人为破坏，陕西黄帝陵管理部门为每一棵古树都建立了专门的电子档案。"],"a":3,"type":"이중 부정","why":"“避免”(피하다)와 “不再”가 겹쳐 ‘다시 훼손되지 않는 것을 피한다’로 뜻이 뒤집힌다.","fix":"为了避免那些树龄超过千年的古柏再遭受人为破坏，陕西黄帝陵管理部门为每一棵古树都建立了专门的电子档案。","words":[["古柏","gǔbǎi","오래된 측백나무"],["黄帝陵","Huángdì Líng","황제릉"],["档案","dàng'àn","기록 파일"],["定居","dìngjū","정착하다"],["源远流长","yuán yuǎn liú cháng","역사가 길다"],["天一阁","Tiānyī Gé","천일각"],["藏书楼","cángshūlóu","장서각"]],"tr":["한 도시의 대중교통이 편리한지는 젊은이들이 어디에 정착할지 정할 때 흔히 고려하는 중요한 요소다.","중국의 장서 문화는 역사가 길며, 닝보의 천일각은 지금 남아 있는 가장 오래된 개인 장서각이다.","온라인 교육은 시간과 공간의 한계를 허물어, 외진 지역의 학생도 질 좋은 교육 자원을 누릴 수 있게 했다.","천 년 넘은 측백나무들이 다시 사람 손에 훼손되지 않도록, 산시성 황제릉 관리 부서는 나무마다 전자 기록을 만들었다."],"ow":[[["定居","dìngjū","정착하다"],["便捷","biànjié","편리하다"]],[["源远流长","yuán yuǎn liú cháng","역사가 길다"],["天一阁","Tiānyī Gé","천일각"],["藏书楼","cángshūlóu","장서각"]],[["在线教育","zàixiàn jiàoyù","온라인 교육"],["优质","yōuzhì","양질의"],["偏远","piānyuǎn","외지다"]],[["古柏","gǔbǎi","오래된 측백나무"],["黄帝陵","Huángdì Líng","황제릉"],["档案","dàng'àn","기록 파일"]]]}]];
